    --seg-on: #383D47; --pill: #262A33; --pill-press: #373C46;
  --menu: rgb(36 39 47 / 0.94); --menu-line: rgb(255 255 255 / 0.08); --menu-hover: rgb(255 255 255 / 0.07);
  --shadow-menu: 0 0 0 1px rgb(255 255 255 / 0.07), 0 16px 44px rgb(0 0 0 / 0.55);
