  --s1: #81A8FF; --s2: #A8C4FE; --s3: #EFB146; --s2-soft: #1E2F54; --s3-soft: #442A00; --ghost: #51555E; --star: #EFB146; --dep-floor: #81A8FF; --dep-kitchen: #F59E6B; --dep-office: #B79CFF;
