/* ---------- the QR: the camera; under it the demo's choice — the places a strip of keys, the tables tiles ---------- */
.guest .gu-demo { padding: 0 0 var(--sp-6); border-radius: 0; }
.guest .gu-demo-t { margin: 0; padding: var(--sp-4); color: var(--ink-2); font-size: var(--fs-sm); line-height: 20px; }
.guest .gu-scanview .gu-chips { gap: 0; margin: 0; padding: 0; box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
.guest .gu-scanview .gu-chip {
  flex: 1 0 auto; min-height: 52px; padding: 0 var(--sp-5); border: 0; border-radius: 0; background: var(--bg); color: var(--ink-2);
