}
.guest .gu-tables > .gu-table[data-rf] { box-shadow: inset 0 -1px 0 0 var(--zl), var(--rim, 0 0 #0000); }
.guest .gu-table:active:not(:disabled) { background: var(--surface-3); }
.guest .gu-table.on { border: 0; background: var(--ok-soft); }
.guest .gu-table-n { font-family: var(--font-timer); font-size: var(--fs-xl); font-weight: var(--fw-semibold); }
