/* ---------- a place's menu: its note a row of the accent's shade; its card; the folders a strip of keys ---------- */
.guest .gu-banner { gap: var(--sp-3); margin: 0; padding: var(--sp-3) var(--sp-4); border-radius: 0; background: var(--accent-soft); color: var(--accent-2); font-size: var(--fs-sm); line-height: 20px; box-shadow: inset 0 -1px 0 0 var(--zl); }
.guest .gu-busy { gap: var(--sp-2); margin: 0; padding: var(--sp-3) var(--sp-4); border-radius: 0; background: var(--warn-soft); color: var(--warn); font-size: var(--fs-sm); font-weight: var(--fw-regular); line-height: 20px; box-shadow: inset 0 -1px 0 0 var(--zl); }
.guest .gu-busy-table { margin: 0; }
