/* three of its dishes: tiles from edge to edge, a line between them */
.guest .gu-hero-arts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0; margin: 0 0 var(--sp-4); box-shadow: inset 0 -1px 0 0 var(--zl); }
