.guest .gu-nav .ks-search-btn {
  flex: none; width: 52px; height: 52px; border-radius: 0; background: var(--bg); color: var(--ink);
  box-shadow: inset -1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl), inset 0 1px 0 0 var(--zl);
}
.guest .gu-nav .ks-search-btn:active { background: var(--surface-3); }
.guest .gu-nav .ks-search-btn.on { background: var(--surface); }
.guest .gu-nav .ks-pills { gap: 0; padding: 0; -webkit-mask-image: none; mask-image: none; }
.guest .gu-nav .ks-pill {
  flex: 1 0 auto; min-width: 112px; height: 52px; min-height: 0; padding: 0 var(--sp-4); border: 0; border-radius: 0;
  background: var(--bg); color: var(--ink-2); font-size: var(--fs-md); font-weight: var(--fw-semibold); transition: none;
