.guest .ks-h {
  display: flex; align-items: center; min-height: 52px; margin: 0; padding: 0 var(--sp-4); background: var(--bg); color: var(--ink);
  font-size: var(--fs-md); font-weight: var(--fw-semibold); line-height: 22px; letter-spacing: 0; text-transform: none;
  box-shadow: inset 0 -1px 0 0 var(--zl);
}
