.guest .ks-grid { gap: 0; background: var(--surface); }
.guest .ks-card {
  gap: var(--sp-1); padding: var(--sp-3) var(--sp-4) var(--sp-4); border-radius: 0; background: var(--surface); transition: background 0.12s;
  box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl), var(--rim, 0 0 #0000);
