.guest .ks-left { margin-top: 0; color: #8A5300; font-size: var(--fs-sm); font-weight: var(--fw-regular); }
.guest .ks-badge { top: var(--sp-3); right: var(--sp-3); min-width: 32px; height: 32px; font-family: var(--font-timer); font-size: var(--fs-md); }
.guest .ks-card.off { opacity: 1; }
.guest .ks-card.off > * { opacity: 0.45; }
.guest .ks-card.off .ks-price { color: var(--ink-2); font-family: var(--font-ui); font-weight: var(--fw-regular); font-size: var(--fs-sm); }
.guest .ks-none { padding: var(--sp-5) var(--sp-4); color: var(--ink-2); font-size: var(--fs-md); }
.guest .ks-end { height: 112px; background: var(--bg); box-shadow: inset 0 1px 0 0 var(--zl); }
/* a pair at a discount: a straight label at the tile's corner, the accent's shade; the price before it struck out */
.guest .gu-pair-badge { top: 0; left: 0; padding: 2px var(--sp-2); border-radius: 0; background: var(--accent-soft); color: var(--accent-2); font-size: var(--fs-sm); font-weight: var(--fw-regular); box-shadow: none; }
