.guest .gu-was { color: var(--ink-3); font-family: var(--font-timer); font-weight: var(--fw-regular); }

/* ---------- the basket's key at the foot: one big pill of the accent ---------- */
.guest .ks-bar { padding: var(--sp-6) var(--sp-4) calc(var(--sp-3) + env(safe-area-inset-bottom, 0px)); background: linear-gradient(rgb(240 242 246 / 0), var(--bg) 45%); }
.guest .ks-bar-btn { gap: var(--sp-3); min-height: 64px; padding: 0 var(--sp-2) 0 var(--sp-2); background: var(--accent); color: var(--accent-ink); }
.guest .ks-bar-btn:active { background: var(--accent-2); }
.guest .ks-bar-n { min-width: 48px; height: 48px; padding: 0 var(--sp-2); border-radius: var(--r-pill); color: var(--accent); font-family: var(--font-timer); font-size: var(--fs-md); font-weight: var(--fw-semibold); }
.guest .ks-bar-t { font-size: var(--fs-md); font-weight: var(--fw-semibold); }
