/* ---------- the sheets: from edge to edge under the header, no radius ---------- */
.guest .ks-scrim { padding: calc(var(--key-h) + env(safe-area-inset-top, 0px)) 0 0; }
.guest .ks-modal { width: 100%; max-height: 100%; border-radius: 0; box-shadow: 0 -1px 0 0 var(--zl); }
.guest .ks-x { top: var(--sp-2); right: var(--sp-3); width: 44px; height: 44px; border-radius: var(--r-pill); background: var(--surface-3); box-shadow: none; }
.guest .ks-x:active { background: var(--pill-press); }
.guest .ks-modal-img { height: min(220px, 28vh); border-radius: 0; background: var(--bg); box-shadow: inset 0 -1px 0 0 var(--zl); }
