.guest .ks-modal-body > :is(.ks-modal-title, .ks-modal-price, .ks-desc, .ks-alg, .ks-muted, .ks-kept, .ks-none, .gu-pay-sum, .gu-pay-tip, .gu-note, .gu-demo-note, .gu-review-p, .gu-review-ic) {
  margin-right: var(--sp-4); margin-left: var(--sp-4);
}
.guest :is(.ks-basket, .gu-pay) .ks-modal-body { padding-top: 0; }
/* the basket's and the payment's head — its name and what is under it — kept at the sheet's top as it scrolls, the
   close key over its end: the key never lies over a tile */
.guest .gu-sheet-h {
  position: sticky; top: 0; z-index: 1; display: flex; flex: none; flex-direction: column; gap: var(--sp-1);
  padding: var(--sp-4) 68px var(--sp-3) var(--sp-4); background: var(--surface); box-shadow: 0 1px 0 0 var(--zl);
}
.guest .gu-sheet-h > .ks-modal-title { padding-right: 0; }
/* (the basket's lines start at the head's line — one line, not two) */
.guest .gu-sheet-h + .ks-lines { margin-top: calc(-1 * var(--sp-1)); }
.guest .gu-sheet-h + .gu-pay-sum { margin-top: var(--sp-4); }
.guest .ks-modal > .ks-x { z-index: 2; }
.guest .ks-modal-title { padding-right: 52px; font-size: var(--fs-xl); font-weight: var(--fw-semibold); line-height: 28px; }
.guest .ks-modal-price { color: var(--ink); font-family: var(--font-timer); font-size: var(--fs-md); font-weight: var(--fw-semibold); }
.guest .ks-weight { font-family: var(--font-ui); font-size: var(--fs-sm); font-weight: var(--fw-regular); }
.guest .ks-desc { margin-top: var(--sp-1); color: var(--ink-2); font-size: var(--fs-sm); line-height: 20px; }
/* the allergens: the words, not chips */
