.guest .ks-muted { color: var(--ink-2); font-size: var(--fs-sm); }
/* a group: its name a row of the shade; the options tiles, two to a row, the chosen one tinted */
.guest .ks-group { gap: 0; margin-top: var(--sp-4); }
.guest .ks-group-t {
  display: block; min-height: 44px; padding: 12px var(--sp-4); background: var(--bg); color: var(--ink-2);
  font-size: var(--fs-sm); font-weight: var(--fw-regular); line-height: 20px; letter-spacing: 0; text-transform: none;
  box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl);
}
.guest .ks-opts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0; }
.guest .ks-opt {
  justify-content: space-between; min-width: 0; min-height: var(--key-h); padding: 0 var(--sp-4); border: 0; border-radius: 0;
  background: var(--surface); color: var(--ink); font-size: var(--fs-md); font-weight: var(--fw-semibold); text-align: left;
  box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl), var(--rim, 0 0 #0000);
}
.guest .ks-opts > .ks-opt[data-rf] { box-shadow: inset 0 1px 0 0 var(--zl), var(--rim, 0 0 #0000); }
.guest .ks-opts > .ks-opt[data-r0] { box-shadow: inset 1px 0 0 0 var(--zl), var(--rim, 0 0 #0000); }
.guest .ks-opts > .ks-opt[data-r0][data-rf] { box-shadow: var(--rim, none); }
/* (3 November, 13:04, the owner: «Каждый блок, у которого есть две линии … должен быть заключен в прямоугольник или
   квадрат») a dish whose sheet ends with its options: the last row of tiles stands on the foot's line — no strip of the
   sheet under it, where «+ ягоды» beside an empty half had no line under it */
/* (the dish's sheet only: the basket's tips and the payment draw their own line under them) */
.guest .ks-modal:not(.gu-basket):not(.gu-pay) .ks-modal-body:has(> .ks-group:last-child) { padding-bottom: 0; }
.guest .ks-opt:active { background: var(--surface-3); }
.guest .ks-opt.on { background: var(--accent-soft); color: var(--accent-2); font-weight: var(--fw-semibold); }
.guest .ks-opt-p { color: var(--ink-2); font-family: var(--font-timer); font-size: var(--fs-sm); }
/* «as last time»: a row of the green shade from edge to edge, its reset a small key */
.guest .ks-modal-body > .ks-kept {
  margin: var(--sp-4) 0 0; padding: var(--sp-1) var(--sp-3) var(--sp-1) var(--sp-4); border-radius: 0; font-weight: var(--fw-regular); line-height: 20px;
  box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl);
