  .front-look .select-pop .select-opt {
    position: relative; min-height: 44px; padding: 0 var(--sp-4) 0 40px; border-radius: 0; background: none; color: var(--ink);
    font-size: var(--fs-sm); font-weight: var(--fw-regular); box-shadow: inset 0 -1px 0 0 var(--menu-line);
  }
  .front-look .select-pop .select-opt:last-child { box-shadow: none; }
  .front-look .select-pop .select-opt.active, .front-look .select-pop .select-opt[aria-selected='true'].active { background: var(--menu-hover); }
  .front-look .select-pop .select-opt[aria-selected='true'] { background: none; color: var(--ink); font-weight: var(--fw-regular); }
  .front-look .select-pop .select-opt > svg { position: absolute; top: 50%; left: 13px; color: var(--accent); transform: translateY(-50%); }
  .front-look .select-pop .select-search { padding: 0; border-bottom: 0; }
  .front-look .select-pop .select-search .search { height: 44px; padding: 0 var(--sp-4); border: 0; border-radius: 0; background: none; box-shadow: inset 0 -1px 0 0 var(--menu-line); }
}
@media (max-width: 700px) {
  /* (the sheet's top rounded as the calendar's sheet — the grid's «square» rule weighs two classes: :root over it) */
  :root .front-look .select-pop { border-radius: var(--r-xl) var(--r-xl) 0 0; }
  .front-look .select-pop .select-opt[aria-selected='true'] { background: none; color: var(--ink); font-weight: var(--fw-regular); }
  .front-look .select-pop .select-opt.active { background: var(--surface-2); }
}

/* ---------- the calendar (ui/calendar.jsx; 10 November, 00:31) ----------
   The owner, of Safari's own calendar under «Свои даты»: «Вот такой выбор дат выглядит супер-позорно». The iPhone's
   month in the menus' layer: its name (a key to the year's months) and the arrows at the top, the days of the week, the
   dates in circles on a grid of 7 × 6 — the same height every month; today in the accent; a range's ends filled, the
   days between them on a band that rounds off where a week or the month ends. On a phone a sheet from the bottom. */
.cal-pop {
  position: fixed; z-index: 95; display: flex; flex-direction: column; overflow: hidden;
  border-radius: 14px; background: var(--menu); color: var(--ink); box-shadow: var(--shadow-menu);
  -webkit-backdrop-filter: blur(24px) saturate(1.6); backdrop-filter: blur(24px) saturate(1.6);
  font-family: var(--font-ui); font-size: var(--fs-md); letter-spacing: 0; text-transform: none;
  transform-origin: top left; animation: menu-in 0.14s ease-out;
}
.cal-scrim { display: none; }
.cal-grab { display: none; }
.cal { display: flex; flex-direction: column; padding: var(--sp-2) var(--sp-3) 0; }
.cal-head { display: flex; align-items: center; justify-content: space-between; min-height: 48px; }
.cal-title {
  display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 var(--sp-2); border: 0; border-radius: var(--r-pill);
  background: none; color: var(--ink); font: inherit; font-size: var(--fs-md); font-weight: var(--fw-semibold); cursor: pointer;
}
.cal-title > svg { color: var(--accent); transition: transform 0.15s; }
.cal-title[aria-expanded='true'] > svg { transform: rotate(90deg); }
.cal-title:hover { background: var(--menu-hover); }
.cal-arrows { display: flex; }
.cal-arrow { display: grid; place-items: center; width: 40px; height: 40px; padding: 0; border: 0; border-radius: 50%; background: none; color: var(--accent); cursor: pointer; }
.cal-arrow:hover:not(:disabled) { background: var(--menu-hover); }
.cal-arrow:disabled { color: var(--ink-3); opacity: 0.35; cursor: default; }
.cal :is(.cal-title, .cal-arrow, .cal-d, .cal-m):focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.cal .cal-d:focus-visible { outline: 0; }
.cal .cal-d:focus-visible .cal-n { box-shadow: 0 0 0 2px var(--accent); }

/* (the columns share the layer's width: as wide as the dates' pill above it, 44 at the most) */
.cal-grid { display: grid; grid-template-columns: repeat(7, minmax(0, 44px)); justify-content: space-between; outline: 0; }
.cal-w { display: grid; place-items: center; height: 28px; color: var(--ink-3); font-size: var(--fs-xs); font-weight: var(--fw-semibold); }
.cal-x { height: 42px; }
.cal-d {
  position: relative; display: grid; place-items: center; height: 42px; padding: 0; border: 0; background: none;
  color: var(--ink); font: inherit; font-size: var(--fs-md); font-variant-numeric: tabular-nums; cursor: pointer;
}
.cal-n { position: relative; z-index: 1; display: grid; place-items: center; width: 38px; height: 38px; border-radius: 50%; }
.cal-d:hover:not(:disabled):not(.lo):not(.hi) .cal-n { background: var(--menu-hover); }
.cal-d.today .cal-n { color: var(--accent); font-weight: var(--fw-semibold); }
.cal-d:is(.lo, .hi) .cal-n { background: var(--accent); color: var(--accent-ink); font-weight: var(--fw-semibold); }
.cal-d:disabled { color: var(--ink-3); opacity: 0.4; cursor: default; }
/* the band: under the days between the ends, from the middle of an end to the middle of the other; it rounds off at a
   week's or the month's edge */
.cal-d.band::before { content: ''; position: absolute; top: 2px; right: 0; bottom: 2px; left: 0; background: var(--accent-soft); }
.cal-d.band.lo::before { left: 50%; }
.cal-d.band.hi::before { right: 50%; }
.cal-d.band:not(.lo):is(.rs, .ms)::before { left: 3px; border-radius: 19px 0 0 19px; }
.cal-d.band:not(.hi):is(.re, .me)::before { right: 3px; border-radius: 0 19px 19px 0; }

/* the year's months: a grid of 3 × 4 as high as the month's, the month on show filled */
.cal-months { display: grid; grid-template-columns: repeat(3, 1fr); grid-template-rows: repeat(4, 1fr); height: 280px; padding: var(--sp-1) 0; }
.cal-m {
  display: grid; place-items: center; margin: 6px; padding: 0; border: 0; border-radius: var(--r-pill); background: none;
  color: var(--ink); font: inherit; font-size: var(--fs-md); cursor: pointer;
}
.cal-m:hover:not(:disabled):not(.on) { background: var(--menu-hover); }
.cal-m.now { color: var(--accent); font-weight: var(--fw-semibold); }
.cal-m.on { background: var(--accent); color: var(--accent-ink); font-weight: var(--fw-semibold); }
.cal-m:disabled { color: var(--ink-3); opacity: 0.4; cursor: default; }

.cal-note { min-height: 44px; margin: 0; padding: var(--sp-3) var(--sp-4); color: var(--ink-2); font-size: var(--fs-sm); box-shadow: inset 0 1px 0 0 var(--menu-line); }

@media (max-width: 700px) {
  .cal-scrim { display: block; position: fixed; inset: 0; z-index: 94; background: var(--scrim); animation: fade-in 0.16s ease-out; }
  .cal-pop {
    top: auto; right: 0; bottom: 0; left: 0; width: auto; border-radius: var(--r-xl) var(--r-xl) 0 0; background: var(--surface);
    box-shadow: 0 -8px 30px rgb(0 0 0 / 0.18); padding-bottom: env(safe-area-inset-bottom); animation: rise 0.18s ease-out;
    -webkit-backdrop-filter: none; backdrop-filter: none;
  }
  .cal-grab { display: block; width: 36px; height: 5px; margin: 8px auto 0; border-radius: 3px; background: var(--line-2); }
  .cal { padding: 0 var(--sp-4); }
  .cal-grid { grid-template-columns: repeat(7, 1fr); }
  .cal-d, .cal-x { height: 46px; }
  .cal-n { width: 42px; height: 42px; }
  .cal-d.band:not(.lo):is(.rs, .ms)::before { left: 2px; border-radius: 21px 0 0 21px; }
  .cal-d.band:not(.hi):is(.re, .me)::before { right: 2px; border-radius: 0 21px 21px 0; }
  .cal-months { height: 304px; }
}
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) {
  .front-look .select-pop, .cal-pop, .cal-scrim { animation: none; }
}

/* a date field (DateField): a list's field that opens the calendar — its icon stays as it is when open */
.date-field.open .select-chevron { color: var(--accent); transform: none; }
.date-field:disabled { background: var(--surface-2); color: var(--ink-3); cursor: default; }

/* ---------- the person's card under the avatar (10 November, 01:08) ----------
   The owner, of its square language keys and the framed «Это устройство»: «Этот блок надо собрать аккуратнее — много
   острых углов». The menus' layer: the name and the e-mail at the top; the language a segmented control of the iPhone
   (a rounded track, the chosen part raised on it); the keys rows across the card with a hair between them — nothing
   square inside a rounded card. (:root — over the grid's «square» rule, 92-office-grid.css) */
:root .of-me-pop {
  gap: 0; min-width: 264px; padding: 0; overflow: hidden; border: 0; border-radius: 14px; background: var(--menu); box-shadow: var(--shadow-menu);
  -webkit-backdrop-filter: blur(24px) saturate(1.6); backdrop-filter: blur(24px) saturate(1.6); transform-origin: top left; animation: menu-in 0.14s ease-out;
}
:root .of-me-pop .of-me-who { padding: var(--sp-4) var(--sp-4) var(--sp-3); }
:root .of-me-pop .lang { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2px; margin: 0 var(--sp-4) var(--sp-4); padding: 2px; border: 0; border-radius: 9px; background: var(--seg-track); }
:root .of-me-pop .lang-btn {
  min-width: 0; height: 32px; min-height: 32px; padding: 0; border: 0; border-radius: 7px; background: none; box-shadow: none;
  color: var(--ink); font-size: var(--fs-sm); font-weight: var(--fw-medium);
}
:root .of-me-pop .lang-btn.on { background: var(--seg-on); color: var(--ink); box-shadow: 0 1px 3px rgb(0 0 0 / 0.14), 0 0 0 0.5px rgb(0 0 0 / 0.05); }
:root .of-me-pop .of-me-keys { gap: 0; box-shadow: inset 0 1px 0 0 var(--menu-line); }
:root .of-me-pop .of-me-keys .btn {
  justify-content: flex-start; gap: var(--sp-3); width: 100%; height: 48px; min-height: 48px; padding: 0 var(--sp-4); border: 0; border-radius: 0;
  background: none; box-shadow: none; color: var(--ink); font-size: var(--fs-sm); font-weight: var(--fw-regular);
}
:root .of-me-pop .of-me-keys .btn + .btn { box-shadow: inset 0 1px 0 0 var(--menu-line); }
:root .of-me-pop .of-me-keys .btn:hover { background: var(--menu-hover); }
:root .of-me-pop .of-me-keys .btn svg { color: var(--ink-2); }
@media (prefers-reduced-motion: reduce) { :root .of-me-pop { animation: none; } }

/* «Топ блюд» → «Показать все» (01:25, the owner, of the first list: «сейчас каша»): a table in the sheet — the place
   muted in its own narrow column before the name, the portions, the share and the money in columns of their own at the
   right; one line a dish, the name cut with «…» rather than wrapped; from edge to edge; on a phone the rows of «Чеки» */
.td-table { table-layout: fixed; width: 100%; }
