.front-look .mg-foot > .mg-state { display: flex; grid-column: span 3; align-items: center; min-width: 0; padding: var(--sp-2) var(--px); background: var(--surface); color: var(--ink-2); font-size: var(--fs-sm); line-height: 18px; }
.front-look .qr-foot > .mg-state { grid-column: span 4; }
.front-look :is(.mg-foot, .mg-keys, .mg-open) > .dt-key { padding: var(--sp-1) var(--sp-3); white-space: normal; text-align: center; line-height: 18px; }
.front-look :is(.mg-foot, .mg-keys) > .dt-key:disabled { color: var(--ink-3); cursor: default; }
.front-look :is(.mg-foot, .mg-keys) > .dt-key:disabled > svg { color: var(--ink-3); }
.front-look :is(.mg-foot, .mg-keys) > .dt-key.acc:disabled { background: var(--surface-2); box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
/* the review: how it was read a row; each table a part of the block — its name, how it was read, what it is; each column
   a row: what RUVO needs, the file's column (two cells), an example (two) */
.front-look .of-page > .mg-status { margin: 0; padding: var(--sp-3) var(--px); border-radius: 0; box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .card > .mg-tables { gap: 0; margin: 0 calc(-1 * var(--px)) calc(-1 * var(--py)); }
.front-look .mg-tables > .mg-table { gap: 0; padding: 0; border: 0; border-radius: 0; box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mg-table-head { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); align-items: stretch; gap: 0; min-height: 56px; box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .mg-table-head > .grow { display: flex; grid-column: span 2; flex-wrap: wrap; align-items: center; gap: 0 6px; min-width: 0; padding: var(--sp-2) var(--px); }
.mg-via { display: flex; align-items: center; padding: var(--sp-2) var(--sp-3); color: var(--ink-3); font-size: var(--fs-sm); }
.mg-via.ai { color: var(--accent); }
:root .front-look .mg-table-head > .select.mg-kind, :root .front-look .mg-map-row > .select, :root .front-look .mg-cat > .select {
  grid-column: span 2; width: auto; height: auto; min-height: 52px; padding: 0 var(--sp-3); border: 0; border-radius: 0; background: var(--surface); box-shadow: inset 1px 0 0 0 var(--zl); font-size: var(--fs-md);
}
:root .front-look .mg-table-head > .select.mg-kind:hover, :root .front-look .mg-map-row > .select:hover, :root .front-look .mg-cat > .select:hover { background: var(--surface-2); }
.front-look .mg-table > .muted.small { padding: var(--sp-3) var(--px); }
.front-look .mg-map { display: flex; flex-direction: column; gap: 0; }
.front-look .mg-map-row { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); grid-template-rows: auto; align-items: stretch; gap: 0; min-height: 52px; box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .mg-map-row:last-child { box-shadow: none; }
.front-look .mg-map-f { display: flex; align-items: center; min-width: 0; padding: var(--sp-2) var(--px); font-weight: var(--fw-regular); }
.front-look .mg-map-ex { display: flex; grid-column: span 2; align-items: center; min-width: 0; padding: var(--sp-2) var(--sp-3); box-shadow: inset 1px 0 0 0 var(--zl); }
/* the categories: the file's (two cells), RUVO's (two), a new one's name (one) */
.front-look .card > .mg-cats { gap: 0; margin: 0 calc(-1 * var(--px)) calc(-1 * var(--py)); box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mg-cat { grid-template-columns: repeat(5, minmax(0, 1fr)); align-items: stretch; gap: 0; min-height: 52px; box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .mg-cat:last-child { box-shadow: none; }
.front-look .mg-cat > .mg-cat-src { display: flex; grid-column: span 2; flex-wrap: wrap; align-items: center; gap: 0 6px; min-width: 0; padding: var(--sp-2) var(--px); }
.front-look .mg-cat > svg { display: none; }
.front-look .mg-cat:has(> span:empty:last-child) > .select { grid-column: span 3; }
.front-look .mg-cat > span:empty:last-child { display: none; }
.front-look .mg-cat > .mg-cat-name { min-width: 0; height: auto; min-height: 52px; padding: 0 var(--sp-3); border: 0; border-radius: 0; background: var(--surface); box-shadow: inset 1px 0 0 0 var(--zl); }
.front-look .mg-cat > .mg-cat-name:focus { box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -2px 0 0 var(--accent); }
/* the notes rows; a refusal a row of the bad shade */
.front-look .card > .mg-issues { gap: 0; margin: 0 calc(-1 * var(--px)) calc(-1 * var(--py)); box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mg-issues > li { padding: var(--sp-2) var(--px); box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .mg-issues > li:last-child { box-shadow: none; }
.front-look .of-page > .mg-err { margin: 0; padding: var(--sp-3) var(--px); border-radius: 0; box-shadow: inset 0 -1px 0 0 var(--zl); }
/* done: what came, the pages to open a row of keys — the first takes what the others leave of the five */
.front-look .dt-keys.mg-open { gap: 0; align-items: stretch; }
.front-look .card > .mg-open { margin: var(--sp-2) calc(-1 * var(--px)) calc(-1 * var(--py)); box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mg-open > .dt-key { justify-content: space-between; padding: 0 var(--px); }
.front-look .mg-open > .dt-key:first-child:nth-last-child(4) { grid-column: span 2; }
.front-look .mg-open > .dt-key:first-child:nth-last-child(3) { grid-column: span 3; }
.front-look .mg-open > .dt-key:first-child:nth-last-child(2) { grid-column: span 4; }
.front-look .mg-open > .dt-key:only-child { grid-column: 1 / -1; }
.front-look .mg-open > .dt-key:first-child { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
.front-look .mg-open > .dt-key:not(:first-child) { box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
.front-look .qr-done { gap: 0; }
.front-look .qr-done > .qr-done-t { display: flex; flex-direction: column; gap: 2px; padding: var(--sp-3) var(--px); }
/* the history rows; the undone one's word */
.front-look .card > .mg-history { margin: 0 calc(-1 * var(--px)) calc(-1 * var(--py)); box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mg-history > li { padding: var(--sp-3) var(--px); border: 0; box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .mg-history > li:last-child { box-shadow: none; }
.mg-undone { color: var(--ink-3); font-size: var(--fs-sm); }
/* app.ruvo.ac's «Что придёт»: its notes rows */
.front-look #qr-what > .qr-notes { gap: 0; margin: 0 calc(-1 * var(--px)); padding: 0; list-style: none; box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look #qr-what > .qr-notes > li { padding: var(--sp-2) var(--px); box-shadow: inset 0 -1px 0 0 var(--zl); }
@media (max-width: 700px) {
  /* a phone: the steps a row of three, the old system a row under them; the keys a third each under the words */
  .front-look .mg-steps > li { aspect-ratio: auto; min-height: 52px; padding: 0 var(--sp-2); font-size: var(--fs-sm); }
  .front-look .mg-keys > .mg-src { grid-column: 1 / -1; aspect-ratio: auto; min-height: 56px; }
  .front-look .dt-keys.mg-keys > .dt-key { order: 0; grid-row: auto; flex-direction: row; }
  .front-look .mg-block > .mg-drop { aspect-ratio: 2 / 1; min-height: 0; }
  .front-look .mg-foot > .mg-state, .front-look .qr-foot > .mg-state { grid-column: 1 / -1; aspect-ratio: auto; min-height: 52px; padding-inline: var(--sx, 16px); box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .mg-block > .mg-files > li { flex-wrap: nowrap; padding-left: var(--sx, 16px); }
  .front-look .mg-block > .mg-files > li > .grow { flex: 1 1 auto; flex-direction: column; align-items: flex-start; gap: 0; }
  .front-look .mg-block > .mg-files > li > .small { flex: none; max-width: 40%; text-align: right; }
  .front-look .mg-open > .dt-key { flex-direction: row; font-size: var(--fs-md); }
  .front-look .dt-keys.mg-foot > .dt-key.acc { order: 0; grid-row: auto; grid-column: auto; }
  .front-look .mg-foot > .dt-key { aspect-ratio: auto; min-height: 56px; }
  .front-look .mg-foot > .dt-key:nth-child(2) { grid-column: span 2; }
  .front-look .dt-keys.mg-foot.qr-foot > .dt-key.acc { grid-column: 1 / -1; flex-direction: row; font-size: var(--fs-md); }
  .front-look .mg-table-head { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .front-look .mg-table-head > .grow { grid-column: 1 / -1; padding-inline: var(--sx, 16px); box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .mg-via { padding-left: var(--sx, 16px); }
  .front-look .mg-map-row { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .front-look .mg-map-f { padding-inline: var(--sx, 16px) var(--sp-2); }
  .front-look .mg-map-ex { grid-column: 1 / -1; padding: 0 var(--sx, 16px) var(--sp-2); box-shadow: none; }
  .front-look .mg-cat { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .front-look .mg-cat > .mg-cat-src { grid-column: 1 / -1; padding-inline: var(--sx, 16px); box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .mg-cat:has(> span:empty:last-child) > .select { grid-column: 1 / -1; }
  :root .front-look .dt-keys.mg-open > .dt-key { grid-column: 1 / -1; min-height: 52px; aspect-ratio: auto; }
}

/* ---------- «Заказы на сайте», «Сайт для заказов» (app.ruvo.ac) ---------- */
/* the orders: where an order is now — a word of its colour, no pill */
.site-st.ok { color: var(--ok); }
.site-st.warn { color: var(--warn); }
.site-st.bad { color: var(--bad); }
.front-look .of-page > .pg-nums.site-kpis { margin: 0; }
/* (the page's settings: 99-site.css — on the grid since 11 November, 14:33) */
}

/* ---------- «Бронирования» (app.ruvo.ac) ---------- */
/* the day's bar a row of the five: the day between its arrows two cells, how many — and «Сегодня» back — one, the views
   an iOS segmented control in the last two */
.front-look .of-page > .bk-daybar { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); align-items: stretch; gap: 0; padding: 0; box-shadow: inset 0 -1px 0 0 var(--zl); }
/* (12 November: the day's bar a cell of the grid's height — its line on the sidebar's line) */
.bk-daybar > .bk-nav { position: relative; display: grid; grid-column: span 2; grid-template-columns: var(--cell-h, 56px) minmax(0, 1fr) var(--cell-h, 56px); align-items: stretch; min-height: var(--cell-h, 56px); }
.front-look .bk-nav > .icon-btn { width: auto; height: auto; border-radius: 0; background: none; box-shadow: none; }
.front-look .bk-nav > .icon-btn:hover { background: var(--surface-2); }
.front-look .bk-nav > .bk-day { width: auto; justify-content: center; border-radius: 0; }
.bk-daybar > .bk-sum-cell { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-2); min-width: 0; padding: 0 var(--sp-2) 0 var(--px); box-shadow: inset 1px 0 0 0 var(--zl); }
.bk-sum-cell > .bk-sum { min-width: 0; margin: 0; overflow: hidden; font-size: var(--fs-sm); text-overflow: ellipsis; white-space: nowrap; }
.bk-today { flex: none; padding: var(--sp-1) var(--sp-2); border: 0; border-radius: 0; background: none; color: var(--accent); font: inherit; font-size: var(--fs-sm); font-weight: var(--fw-semibold); cursor: pointer; }
.bk-today:hover { background: var(--surface-2); }
.front-look .bk-daybar > .bk-views-cell { grid-column: span 2; justify-content: flex-end; min-height: var(--cell-h, 56px); box-shadow: inset 1px 0 0 0 var(--zl); }
/* (11 November, 14:33) the views fill their two cells — no empty one before them */
:root .front-look .bk-daybar > .bk-views-cell > .seg.cs-tabs { width: 100%; grid-auto-columns: minmax(0, 1fr); }
/* the plan's row: the halls an iOS segmented control, then «Столы на 14:15», the slider over the day's hours with the
   day's bookings on it, «Сейчас» a quiet key */
.bkp-tools .bkp-head.cs-p-tabs { gap: var(--sp-4); }
.bkp-at { display: flex; flex: none; flex-direction: column; align-items: flex-start; gap: 0; }
.bkp-at-l { color: var(--ink-2); font-size: var(--fs-xs, 12px); line-height: 14px; white-space: nowrap; }
.bkp-time .bkp-clock { min-width: 0; font-size: var(--fs-lg); line-height: 24px; text-align: left; }
.bkp-track { position: relative; display: block; flex: 1 1 auto; min-width: 120px; padding-bottom: 14px; }
.bkp-track > .bkp-range { display: block; width: 100%; min-width: 0; margin: 0; }
.bkp-marks { position: absolute; inset: 0 0 14px; pointer-events: none; }
.bkp-marks > i { position: absolute; top: 50%; width: 6px; height: 6px; margin: -3px 0 0 -3px; border-radius: 50%; background: var(--warn); box-shadow: 0 0 0 2px var(--surface); }
.bkp-hours { position: absolute; left: 0; right: 0; bottom: 0; height: 14px; pointer-events: none; }
.bkp-hours > span { position: absolute; top: 0; color: var(--ink-3); font-size: 11px; line-height: 14px; transform: translateX(-50%); }
.bkp-now { flex: none; padding: var(--sp-1) var(--sp-2); border: 0; border-radius: 0; background: none; color: var(--accent); font: inherit; font-size: var(--fs-sm); font-weight: var(--fw-semibold); cursor: pointer; }
.bkp-now:hover { background: var(--surface-2); }
@media (max-width: 700px) {
  .front-look .of-page > .bk-daybar { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .bk-daybar > .bk-nav { grid-column: 1 / -1; box-shadow: inset 0 -1px 0 0 var(--zl); }
  .bk-daybar > .bk-sum-cell { grid-column: 1 / -1; min-height: 44px; padding-left: var(--sx, 16px); box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .bk-daybar > .bk-views-cell { grid-column: 1 / -1; box-shadow: none; }
}
@media (max-width: 700px) {
  /* (the visual audit of the lines, 12 November) «Отчёт в Telegram» on a phone: the alerts' last row draws the line over
     «Так придёт сообщение» — its head none of its own */
  .front-look .tg-col + .tg-side > .tg-block:first-child > .pg-head:first-child { box-shadow: inset 0 -1px 0 0 var(--zl); }
}

/* «Лояльность» in the brand's look (11 November, 03:26, the owner: «делай все остальные страницы бэка, но только
   чётко»; ui/office-loyalty.jsx, office-coupons.jsx, office-ratings.jsx). The guests: their figures squares — the
   guests, each level a key that leaves only its guests, the points —, the search and the keys a row of the five, the
   list a block. The levels: the points' share of a bill a cell of the keys' row, «Исходные правила», «+ Уровень» and the
   accent's «Сохранить» keys, the levels a list. The discounts: two lists, each its «+» a key at the end of its head;
   «идёт», «PIN», «новая» quiet words (pills only for the tabs and a sheet's main key). */

/* a key at the end of a block's head: a column of the five, the head's height, a line at its left (a fifth of the
   block's width — not of the head's, which is narrower by its padding: the settings' audit, 11 November, five pixels off
   the column's line under it) */
.pg-head > .pg-hkey {
  display: flex; flex: none; align-items: center; justify-content: center; gap: var(--sp-2); align-self: stretch; width: calc((100% + var(--px) + var(--sp-2)) / 5); min-width: 0; margin: 0 calc(-1 * var(--sp-2)) 0 auto; padding: 0 var(--sp-3);
  border: 0; border-radius: 0; background: var(--surface); color: var(--ink); font: inherit; font-size: var(--fs-md); font-weight: var(--fw-semibold); white-space: nowrap; cursor: pointer;
  box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--line-2);
}
.pg-head > .pg-count + .pg-hkey { margin-left: 0; }
.pg-head:has(> .pg-hkey) > .pg-count { padding-right: var(--px); }
.pg-head > .pg-hkey > svg { flex: none; color: var(--ink-2); }
.pg-head > .pg-hkey:hover { background: var(--surface-2); }
.pg-head > .pg-hkey:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.pg-head > .pg-hkey.acc { background: var(--accent); color: var(--accent-ink); box-shadow: none; }
.pg-head > .pg-hkey.acc > svg { color: currentColor; }
.pg-head > .pg-hkey.acc:hover { background: color-mix(in oklab, var(--accent) 88%, var(--ink)); }
.pg-head > .pg-hkey > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; }

/* a key of the page's row that cannot be pressed now (the levels' «Сохранить» before a change, the sixth level) */
.dt-keys > .dt-key:disabled { background: var(--surface); color: var(--ink-3); cursor: default; }
.dt-keys > .dt-key:disabled > svg { color: var(--ink-3); }
.dt-keys > .dt-key.acc:disabled { background: var(--surface-2); color: var(--ink-3); box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }

/* a field in the row of keys: its name over it, as a form's cell */
.dt-keys > .dt-field { display: flex; flex-direction: column; justify-content: center; gap: 2px; min-width: 0; padding: var(--sp-2) var(--px); background: var(--surface); cursor: text; }
.dt-field-l { overflow: hidden; color: var(--ink-2); font-size: var(--fs-sm); line-height: 18px; white-space: nowrap; text-overflow: ellipsis; }
.dt-field > input { width: 100%; min-width: 0; height: 24px; padding: 0; border: 0; outline: 0; background: transparent; color: var(--ink); font: inherit; font-size: var(--fs-md); line-height: 24px; }
.dt-keys > .dt-field:focus-within { box-shadow: inset 0 -2px 0 0 var(--accent); }
.lv-keys.k2 > .dt-field { grid-column: span 3; }
.lv-keys.k3 > .dt-field { grid-column: span 2; }
@media (max-width: 700px) {
  /* a phone's: the field a row, the keys under it — a third each, the last on to the row's end */
  .lv-keys > .dt-field { grid-column: 1 / -1; aspect-ratio: auto; min-height: 60px; padding: var(--sp-2) var(--sx, 16px); }
  .lv-keys > .dt-key.acc { order: 0; grid-row: auto; grid-column: auto; }
  .lv-keys.k2 > .dt-key.acc { grid-column: span 2; aspect-ratio: 4 / 1; }
  .lv-keys > .dt-key:nth-child(2) { box-shadow: inset 0 -1px 0 0 var(--zl); }
}

/* the levels: the list from edge to edge (its fields the rounded blocks of a table's row) */
@media (min-width: 701px) { .front-look .levels-table td.edit-cell { width: 56px; } }

/* the discounts: their marks quiet words; the deleted ones rows, «Вернуть» a key at their end */
.front-look .disc-table .st:not(.c-phone) { display: inline; height: auto; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; font-size: var(--fs-sm); font-weight: var(--fw-regular); line-height: inherit; white-space: nowrap; }
.front-look .disc-table .st.c-phone { height: auto; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; font-size: var(--fs-sm); font-weight: var(--fw-regular); }
.front-look .disc-table .st.st-ok { color: var(--ok); }
.front-look .disc-table .st.st-draft { color: var(--accent); }
.front-look .disc-table .st.st-sent { color: var(--ink-2); }
.disc-gone { margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--zl); }
.disc-gone > li { display: flex; align-items: stretch; min-height: 56px; box-shadow: inset 0 -1px 0 0 var(--zl); }
.disc-gone-t { display: flex; flex: 1 1 auto; align-items: center; min-width: 0; padding: var(--sp-2) var(--px); color: var(--ink); font-weight: var(--fw-semibold); }
.disc-gone-t > span { margin-left: 4px; color: var(--ink-2); font-weight: var(--fw-regular); }
.disc-gone > li > .pg-hkey { display: flex; flex: none; align-items: center; justify-content: center; gap: var(--sp-2); width: 20%; padding: 0 var(--sp-3); border: 0; border-radius: 0; background: var(--surface); color: var(--ink); font: inherit; font-weight: var(--fw-semibold); cursor: pointer; box-shadow: inset 1px 0 0 0 var(--zl); }
.disc-gone > li > .pg-hkey:hover { background: var(--surface-2); }
.disc-gone > li > .pg-hkey > svg { color: var(--ink-2); }

@media (max-width: 700px) {
  /* a phone's head key: a third of the row */
  .pg-head > .pg-hkey { width: calc((100% + var(--px) + var(--sp-2)) / 3); flex-direction: column; gap: 2px; padding: 0 var(--sp-2); font-size: var(--fs-sm); line-height: 18px; }
  .disc-gone > li > .pg-hkey { width: calc(100% / 3); }
}
@media (min-width: 701px) and (max-width: 1239px) {
  .pg-head > .pg-hkey { flex-direction: column; gap: 2px; padding: 0 var(--sp-2); font-size: var(--fs-sm); line-height: 18px; }
}

/* (the documents' rule left a single search without its two thirds on a phone: a page with two keys after its search —
   «Гости» — had the search a row of its own under an empty two thirds) the search two thirds beside the accent's key */
@media (max-width: 700px) { :root .doc-keys.s3 > .dt-search { grid-column: span 2; } }

/* the levels on a phone: no table going sideways — a level a block of cells: its name a row across, then where it starts,
   the discount and the points, each named over its field, then what a 3 000 bill gives, its guests and the bin */
@media (max-width: 700px) {
  .front-look #lv-list > .table-wrap { overflow: visible; }
  .front-look .tbl-data.levels-table, .front-look .levels-table tbody { display: block; }
  .front-look .levels-table thead { display: none; }
  .front-look .levels-table tr { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); box-shadow: inset 0 -1px 0 0 var(--zl); }
  :root .front-look .table-wrap > .tbl-data.levels-table td { position: static; display: flex; flex-direction: column; justify-content: center; align-items: flex-start; gap: 4px; min-width: 0; max-width: none; height: auto; padding: var(--sp-2) var(--sp-3); border: 0; background: none; text-align: left; white-space: normal; box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl); }
  :root .front-look .table-wrap > .tbl-data.levels-table td:first-child { grid-column: 1 / -1; padding: var(--sp-3) var(--sx, 16px) var(--sp-2); box-shadow: none; }
  :root .front-look .table-wrap > .tbl-data.levels-table td:nth-child(2), :root .front-look .table-wrap > .tbl-data.levels-table td:nth-child(5) { padding-left: var(--sx, 16px); box-shadow: inset 0 1px 0 0 var(--zl); }
  .front-look .levels-table td[data-label]::before { content: attr(data-label); color: var(--ink-3); font-family: var(--font-ui); font-size: var(--fs-xs); font-weight: var(--fw-regular); line-height: 16px; white-space: nowrap; }
  .front-look .levels-table td .cell-input { width: 100%; max-width: 120px; font-size: 16px; }
  .front-look .levels-table td:first-child .cell-input { max-width: none; }
  :root .front-look .table-wrap > .tbl-data.levels-table td.edit-cell { width: auto; align-items: stretch; padding: 0; }
  .front-look .levels-table td.edit-cell .icon-btn { width: 100%; height: 100%; min-height: 56px; border-radius: 0; }
  .front-look .levels-table td.edit-cell:empty { display: none; }
  /* (the first level has no bin: its guests on to the row's end) */
  .front-look .levels-table td:nth-child(6):has(+ td.edit-cell:empty) { grid-column: span 2; }
}

/* a narrower computer: the guests' squares their names and lines on two lines rather than cut; the card's number out of
   the list (it is on the guest's card, and the search finds it) */
@media (min-width: 701px) and (max-width: 1239px) {
  #guests-nums .pg-num-l, #guests-nums .pg-num-s { display: -webkit-box; white-space: normal; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
  .front-look .guests-table :is(th, td):nth-child(2) { display: none; }
  .front-look .guests-table td .cell-sub { white-space: nowrap; }
}

/* «Купоны»: a campaign a block from edge to edge — its terms cells, those who qualify rows, the guest's message a bubble
   (a message's own shape), «Выдать N купонов» the accent's key at the end of its foot's row (what it gives the row's
   other four columns); changed terms a row too — what to do, «Отмена», «Сохранить условия» */
.front-look .cp-card > .cp-who > .cp-list { margin: 0 calc(-1 * var(--px)); }
.front-look .cp-card > .cp-who > .cp-list > li { min-height: 52px; padding: var(--sp-2) var(--px); border-bottom: 0; box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .cp-card > .cp-who > .cp-list > li:first-child { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
/* (12 November, the visual audit) those who qualify straight under the terms — the terms' line their top, no strip of the
   card's gap between two lines; the terms' names on two lines rather than cut («Без визито…»); «Выдать 8 купонов» two
   columns of the foot (its words had run 25 px out of the page) */
.front-look .cp-card > :is(.cp-fields, .cp-save) + .cp-who:has(> .cp-list:first-child) { margin-top: calc(-1 * var(--gap, var(--sp-3))); }
.front-look .cp-card > :is(.cp-fields, .cp-save) + .cp-who > .cp-list:first-child > li:first-child { box-shadow: inset 0 -1px 0 0 var(--zl); }
:root .front-look .cp-card > .cp-fields > .dt-field > .dt-field-l { display: block; overflow: visible; white-space: normal; text-overflow: clip; line-height: 16px; overflow-wrap: normal; }
@media (min-width: 701px) { :root .front-look .cp-card > .dt-keys.cp-fields > * { min-height: 76px; } }
.front-look .cp-card > :is(.cp-foot, .cp-save) {
  display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); align-items: stretch; gap: 0; margin: 0 calc(-1 * var(--px)); padding: 0; border-top: 0; box-shadow: inset 0 1px 0 0 var(--zl);
}
.front-look .cp-card > .cp-foot { margin-top: auto; margin-bottom: calc(-1 * var(--py)); }
.front-look .cp-foot > .muted, .front-look .cp-save > .cp-save-t { grid-column: span 4; grid-row: 1; display: flex; align-items: center; min-height: 56px; padding: 0 var(--px); color: var(--ink-2); font-size: var(--fs-sm); }
.front-look .cp-save > .cp-save-t { grid-column: span 3; }
.front-look .cp-card > :is(.cp-foot, .cp-save) > .btn { grid-row: 1; min-height: 56px; height: auto; padding: 0 var(--sp-3); border: 0; border-radius: 0; box-shadow: inset 1px 0 0 0 var(--zl); font-size: var(--fs-md); }
.front-look .cp-card > .cp-foot > .btn { grid-column: 4 / span 2; min-width: 0; }
.front-look .cp-card > .cp-foot > .muted { grid-column: span 3; }
.front-look .cp-card > :is(.cp-foot, .cp-save) > .btn.btn-primary { box-shadow: none; }
.front-look .cp-card > :is(.cp-foot, .cp-save) > .btn.btn-primary:disabled { background: var(--surface-2); color: var(--ink-3); box-shadow: inset 1px 0 0 0 var(--zl); opacity: 1; }
/* (the visual audit of the lines, 12 November) «Выдать купоны» while there is no one: its grey covers the foot's line over
   it and the card's under it — it draws them itself */
.front-look .cp-card > .cp-foot > .btn.btn-primary:disabled { box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
@media (max-width: 700px) { .front-look .cp-card > .cp-foot > .btn.btn-primary:disabled { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); } }
/* (the two cards' own lines under them: «Выданные купоны» draws none over itself) */
.front-look .cp-cols + .pg-block > .pg-head:first-child { box-shadow: none; }
.front-look .cp-card > .cp-save > .btn.btn-ghost { background: var(--surface); color: var(--ink); }
/* the coupons' states quiet words */
.front-look .cp-table .st { display: inline; height: auto; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; font-size: var(--fs-sm); font-weight: var(--fw-semibold); line-height: inherit; white-space: nowrap; }
.front-look .cp-table .st.st-ok { color: var(--ok); }
.front-look .cp-table .st.st-sent { color: var(--accent); }
.front-look .cp-table .st.st-bad { color: var(--bad); }
.front-look .cp-table .st.st-muted { color: var(--ink-3); }
@media (max-width: 700px) {
  .front-look .cp-card > :is(.cp-foot, .cp-save) { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .front-look .cp-foot > .muted { grid-column: 1 / -1; grid-row: 1; min-height: 44px; }
  .front-look .cp-card > .cp-foot > .btn { grid-column: 1 / -1; grid-row: 2; }
  .front-look .cp-save > .cp-save-t { grid-column: 1 / -1; min-height: 44px; }
  .front-look .cp-card > .cp-save > .btn { grid-row: 2; }
  .front-look .cp-card > .cp-save > .btn.btn-primary { grid-column: span 2; }
  .front-look .cp-card > .cp-save > .btn.btn-ghost { box-shadow: inset 0 1px 0 0 var(--zl); }
}

/* «Оценки гостей»: a rating's state a quiet word; who carried the orders rows from edge to edge */
/* (the visual audit, 11 November) a rating a row of the grid: its words four columns, «Разобрано…» the fifth, a key of
   the row's height; what was done a row of the five under them — the field three columns, «Отмена», the accent's
   «Разобрано». On a phone the words a row, the key a row under them */
.front-look .rt-list > li.rt-row { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); align-items: stretch; gap: 0; padding: 0; }
.front-look .rt-row > .rt-body { display: flex; flex-direction: column; grid-column: 1 / -1; align-items: flex-start; gap: var(--sp-2); min-width: 0; padding: var(--sp-3) var(--px); }
.front-look .rt-row:has(> .rt-deal) > .rt-body { grid-column: 1 / 5; }
.front-look .rt-row > .rt-deal { grid-column: 5; min-height: 56px; box-shadow: inset 1px 0 0 0 var(--zl); }
.front-look .rt-row > .rt-form { grid-column: 1 / -1; box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .rt-row > .rt-form > * { box-shadow: inset 1px 0 0 0 var(--zl); }
.front-look .rt-row > .rt-form > .dt-field { grid-column: span 3; box-shadow: none; }
.front-look .rt-row > .rt-form > .dt-field:focus-within { box-shadow: inset 0 -2px 0 0 var(--accent); }
.front-look .rt-row > .rt-form > .dt-key.acc { box-shadow: none; }
@media (max-width: 700px) {
  .front-look .rt-list > li.rt-row { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .front-look .rt-row:has(> .rt-deal) > .rt-body { grid-column: 1 / -1; padding-left: var(--sx, 16px); padding-right: var(--sx, 16px); }
  .front-look .rt-row > .rt-deal { grid-column: 1 / -1; box-shadow: inset 0 1px 0 0 var(--zl); }
  .front-look .rt-row > .rt-form > .dt-field { grid-column: 1 / -1; }
  .front-look .rt-row > .rt-form > .dt-key { grid-column: span 1; min-height: 56px; box-shadow: inset 0 1px 0 0 var(--zl); }
  .front-look .rt-row > .rt-form > .dt-key.acc { grid-column: span 2; box-shadow: none; }
}
.front-look .rt-row .st { display: inline; height: auto; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; font-size: var(--fs-sm); font-weight: var(--fw-semibold); line-height: inherit; white-space: nowrap; }
.front-look .rt-row .st.st-ok { color: var(--ok); }
.front-look .rt-row .st.st-bad { color: var(--bad); }

/* a guest's card: its three figures cells across the sheet under its head (no rounded boxes in a square sheet), the
   name's cell right under them */
.front-look .sheet-body > .kpi-row.compact { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0; margin: calc(-1 * var(--sheet-top, var(--sp-5))) calc(-1 * var(--edge, var(--sx))) 0; padding: 0; }
.front-look .sheet-body > .kpi-row.compact > .tile { display: flex; flex-direction: column; gap: 2px; min-height: 0; padding: var(--sp-3) var(--edge, var(--sx)); border: 0; border-radius: 0; background: var(--surface); box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
.front-look .sheet-body > .kpi-row.compact > .tile:first-child { box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .sheet-body > .kpi-row.compact > .tile .tile-l { color: var(--ink-2); font-size: var(--fs-sm); font-weight: var(--fw-regular); line-height: 18px; }
.front-look .sheet-body > .kpi-row.compact > .tile .tile-v { font-size: 22px; line-height: 28px; }
.front-look .sheet-body > .kpi-row.compact > .tile .tile-sub { color: var(--ink-2); font-size: var(--fs-sm); line-height: 18px; }
/* (the visual audit of the lines, 12 November) the tiles draw their line under them: the name's field on it, not a pixel
   under it */
.front-look .sheet-body > .kpi-row.compact + .field { margin-top: calc(-1 * var(--gap)); }

/* ---------- «Купоны» (the visual audit, 11 November) ----------
   a campaign's terms a row of the five — a field a column (they had stood in thirds and quarters, off the page's columns),
   who qualifies now the rest of it; changed — a row under it: what that means, «Отмена», the accent's «Сохранить
   условия». On a phone a field a row, as an iPhone's form */
.front-look .cp-card > .dt-keys:is(.cp-fields, .cp-save) { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0; margin: 0 calc(-1 * var(--px)); padding: 0; box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
.front-look .cp-card > .dt-keys.cp-fields.cp-3 > .cp-now { grid-column: span 2; }
.front-look .cp-card > .dt-keys.cp-save > .cp-save-t { grid-column: span 3; }
/* (each cell draws the row's lines over and under it too — the row's own lay under the cells' ground) */
.front-look .cp-card > .dt-keys:is(.cp-fields, .cp-save) > * { min-height: 64px; box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
.front-look .cp-card > .dt-keys:is(.cp-fields, .cp-save) > :first-child { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
.front-look .cp-card > .dt-keys:is(.cp-fields, .cp-save) > .dt-field:focus-within { box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl), inset 0 -2px 0 0 var(--accent); }
.front-look .cp-card > .dt-keys:is(.cp-fields, .cp-save) > .dt-field:first-child:focus-within { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -2px 0 0 var(--accent); }
.front-look .cp-card > .dt-keys.cp-save > .dt-key.acc { box-shadow: none; }
.front-look .cp-card > .cp-fields + .cp-save { margin-top: calc(-1 * var(--sp-3) - 1px); }
.front-look .cp-card > .dt-keys > .cp-now { color: var(--ink); }
/* (a field's name and value at its left, as every field of the grid — the card's centred words had centred them) */
.front-look .cp-card > .dt-keys > :is(.dt-field, .dl-words) { align-items: stretch; text-align: left; }
@media (max-width: 700px) {
  .front-look .cp-card > .dt-keys:is(.cp-fields, .cp-save) { grid-template-columns: repeat(3, minmax(0, 1fr)); margin: 0 calc(-1 * var(--sx, 16px)); }
  .front-look .cp-card > .dt-keys.cp-fields > *, .front-look .cp-card > .dt-keys.cp-fields.cp-3 > .cp-now, .front-look .cp-card > .dt-keys.cp-save > .cp-save-t { grid-column: 1 / -1; aspect-ratio: auto; min-height: 56px; box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .cp-card > .dt-keys.cp-save > .dt-key { grid-column: span 1; box-shadow: none; }
  .front-look .cp-card > .dt-keys.cp-save > .dt-key.acc { grid-column: span 2; }
}

/* (13 November, 01:45, the owner on «Уровни и баллы»: the line under «Баллами можно оплатить до, % чека» 12 lower than
   the menu's line beside it — they did not go on one into the other) a page's first row of keys stands as high as the
   menu's first row (48, a key's): a field in it — its name over its value — closer to its lines */
@media (min-width: 701px) {
  .front-look .of-page > .of-head + .dt-keys > .dt-field { min-height: 48px; padding-block: 4px; gap: 0; }
  .front-look .of-page > .of-head + .dt-keys > .dt-field > .dt-field-l { line-height: 16px; }
}

/* «Деньги» on the brand's grid (11 November — the owner, 03:26: «делай все остальные страницы бэка, но только чётко»;
   ui/money-blocks.jsx). A page: its header, its figures squares of the five (Nums), then blocks — a head (the name, what
   it counts, a key at its end), a line of how far when it has steps, its rows. A row: its words, its keys a column each —
   at the row's end when they are few, a row of the five under the words when more (the last row short: the ground after
   it, the line round its end, as the waiter's tables). The lines: a row draws the one over it; a key its own at its left
   (and over it); none doubled. A phone: the words a row, the keys a third each, the icon over the name. */

/* a block closes with a line under it (the owner, 10 November, of a list of one row: «Нет горизонтальной линии»): drawn
   outside it, so the next block's head — its own line over it — covers it; a page's last block keeps it */
.front-look .mb-block { box-shadow: 0 1px 0 0 var(--zl); }
/* (the visual audit, 11 November) …so a list's last row draws none under it — the block's closes it: the two had touched,
   a line twice as thick under «Кассы и сейфы»' and «Места денег»' last rows */
.front-look .mb-block > .table-wrap:last-child > .tbl-data > tbody:last-child > tr:last-child > td,
.front-look .mb-block > .tbl-data:last-child > tbody:last-child > tr:last-child > td { border-bottom-color: transparent; }
/* (13 November) a row of choices right under a block (P&L on a phone: the month's sources and its keys under the table)
   stands a pixel lower — the block's own line under it shows (its cells' ground had covered it: no line between) */
.front-look.mn-app .of-page > .mb-block + .mb-f { margin-top: 1px; }
/* a head right under a row that closes with its own line (the choices' row, a note) draws none over it; notes without a
   head — their first row none */
.front-look.mn-app .of-page > :is(.mb-f, .tg-row) + .pg-block > .pg-head:first-child { box-shadow: none; }
.front-look.mn-app .of-page > :is(.mb-f, .tg-row) + .pg-block > .pg-head:first-child > .pg-hkey { box-shadow: inset 1px 0 0 0 var(--zl); }
.front-look .mb-notes > .mb-list > .mb-item:first-child { --tl: 0 0 #0000; }

/* a row of choices inside a block: each cell draws the line over it and at its left — the block's rows' way (a second
   row's first cell none at its left) */
.front-look .mb-block > .dt-keys.dl-row.mb-f > * { box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl); }
.front-look .mb-block > .dt-keys.dl-row.mb-f > :is(:first-child, :nth-child(5n + 1)) { box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mb-block > .dt-keys.dl-row.mb-f > .dt-key.acc:not(:disabled) { box-shadow: none; }
.front-look .mb-block > .dt-keys.dl-row.mb-f > :is(.dt-field, .dt-search):focus-within { box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl), inset 0 -2px 0 0 var(--accent); }
/* what a block found (an upload's facts): its lines one under another, the line over them */
.front-look .mb-block > .mn-facts { display: flex; flex-direction: column; gap: 4px; margin: 0; padding: var(--sp-3) var(--px); list-style: none; box-shadow: inset 0 1px 0 0 var(--zl); font-size: var(--fs-sm); line-height: 20px; }
/* a head inside a block (the lines of a file and their sums) */
.front-look .pg-head.mb-sub > h3 { flex: 0 1 auto; min-width: 0; margin: 0; overflow: hidden; color: var(--ink); font-size: var(--fs-md); font-weight: var(--fw-semibold); line-height: 22px; white-space: nowrap; text-overflow: ellipsis; }
/* a file to choose on a page: a block a shade apart across the page, as tall as two rows — square, as the page's blocks
   (a sheet's keeps its rounding) */
.front-look .mn-drop.fld-drop { border: 0; color: var(--ink); }
.front-look .of-page > .mn-drop.fld-drop { border-radius: 0; box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .of-page > .mn-drop.fld-drop.over, .front-look .of-page > .mn-drop.fld-drop:focus-within { box-shadow: inset 0 0 0 2px var(--accent); }

/* the line of how far: under the head, the steps done in the colour of done (the first row draws no line over it) */
.front-look .mb-bar { height: 3px; background: var(--surface-3); }
.front-look .mb-bar > span { display: block; height: 100%; background: var(--ok); transition: width 0.3s ease; }
@media (prefers-reduced-motion: reduce) { .front-look .mb-bar > span { transition: none; } }

.front-look .mb-list { margin: 0; padding: 0; list-style: none; }
.front-look .mb-item { --tl: inset 0 1px 0 0 var(--zl); display: block; margin: 0; padding: 0; background: var(--surface); box-shadow: var(--tl); }
.front-look .mb-bar + .mb-list > .mb-item:first-child { --tl: 0 0 #0000; }
.front-look .mb-item.mb-row { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); align-items: stretch; }
.front-look .mb-w { display: flex; align-items: flex-start; gap: var(--sp-3); min-width: 0; padding: var(--sp-3) var(--px); }
.front-look .mb-row > .mb-w { grid-column: span var(--span, 5); align-items: center; }
.front-look .mb-t { display: flex; flex: 1 1 auto; flex-direction: column; gap: 2px; min-width: 0; }
.front-look .mb-n { color: var(--ink); font-size: var(--fs-md); font-weight: var(--fw-semibold); line-height: 22px; overflow-wrap: anywhere; }
.front-look .mb-h { color: var(--ink-2); font-size: var(--fs-sm); line-height: 18px; }
.front-look .mb-t p { margin: 0; }
/* a step's circle: empty — to do; filled — done; dashed — not yet due */
.front-look .mb-mark { display: inline-flex; flex: none; align-items: center; justify-content: center; width: 22px; height: 22px; border: 2px solid var(--line-2); border-radius: 50%; color: var(--accent-ink, #fff); }
.front-look .mb-mark.done { border-color: var(--ok); background: var(--ok); }
.front-look .mb-mark.later { border-style: dashed; }
.front-look .ms-step:is(.done, .later) .mb-n { color: var(--ink-2); }

/* the keys: a column of the five each, 56 high at least; their words wrap inside them */
.front-look :is(.mb-row, .mb-keys) > .dt-key { min-width: 0; min-height: 56px; padding: var(--sp-2) var(--sp-3); white-space: normal; text-align: center; line-height: 18px; }
.front-look :is(.mb-row, .mb-keys) > .dt-key > span { min-width: 0; overflow-wrap: break-word; }
.front-look .mb-row > .dt-key { box-shadow: var(--tl), inset 1px 0 0 0 var(--zl); }
.front-look .mb-keys { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0; }
.front-look .mb-keys > .dt-key { box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl), var(--rim, 0 0 #0000), var(--rb, 0 0 #0000); }
.front-look .mb-keys > .dt-key[data-rf] { box-shadow: inset 0 1px 0 0 var(--zl), var(--rim, 0 0 #0000), var(--rb, 0 0 #0000); }
.front-look .mb-keys > [data-rl] { --rim: 1px 0 0 0 var(--zl); }
/* (a key with nothing under it while the row under it is short: its line below — the grid closed round the ground, as
   round the waiter's tables; «Зарплата ресепшн» … «Премии и бонусы» over the ground were open, 11 November) */
.front-look .mb-keys > [data-rb] { --rb: 0 1px 0 0 var(--zl); }
.front-look :is(.mb-row, .mb-keys) > .dt-key.acc:not(:disabled) { background: var(--accent); color: var(--accent-ink); box-shadow: none; }
.front-look :is(.mb-row, .mb-keys) > .dt-key:disabled { background: var(--surface); color: var(--ink-3); cursor: default; }
.front-look :is(.mb-row, .mb-keys) > .dt-key:disabled > svg { color: var(--ink-3); }
.front-look :is(.mb-row, .mb-keys) > .dt-key[aria-expanded='true'] { background: var(--surface-2); }

/* the sheets of «Деньги» (an entry, a count, the cash spent): their choices of one an iOS segmented control — the grey
   track, the chosen one white and raised — as the back office's; (12 November, the deep visual audit) a field's choice
   («Чьё», «Вид», «Валюта») is the field's strip of cells, as a dish's or a discount's — not a pill at the screen's edge */
:root .front-look.mn-app .sheet .seg:not(.field > .seg) {
  display: inline-grid; align-self: flex-start; grid-auto-flow: column; grid-auto-columns: minmax(max-content, 1fr); align-items: center; gap: 2px; height: 36px; min-height: 36px;
  max-width: 100%; padding: 2px; overflow: visible; border: 0; border-radius: var(--r-pill); background: var(--seg-track); box-shadow: none;
}
:root .front-look.mn-app .sheet .seg:not(.field > .seg) > .seg-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 4px; height: 32px; min-height: 32px; padding: 0 var(--sp-3); border: 0; border-radius: var(--r-pill);
  background: none; box-shadow: none; color: var(--ink); font-size: 13px; font-weight: var(--fw-medium); line-height: 1; white-space: nowrap;
}
:root .front-look.mn-app .sheet .seg:not(.field > .seg) > .seg-btn.on { background: var(--seg-on); color: var(--ink); box-shadow: 0 1px 3px rgb(0 0 0 / 0.14), 0 0 0 0.5px rgb(0 0 0 / 0.05); font-weight: var(--fw-semibold); }
:root .front-look.mn-app .sheet .seg:not(.field > .seg) > .seg-btn > svg { color: currentColor; }
@media (max-width: 700px) {
  :root .front-look.mn-app .sheet .seg:not(.field > .seg) { display: grid; width: 100%; height: auto; grid-auto-columns: minmax(0, 1fr); }
  :root .front-look.mn-app .sheet .seg:not(.field > .seg) > .seg-btn { min-width: 0; height: auto; min-height: 32px; padding: 4px 6px; white-space: normal; text-align: center; line-height: 15px; }
}
/* «Обзор»'s figures: the words under a figure two lines (the month's: what came in and what went out — a line each) */
@media (min-width: 701px) {
  #mn-nums .pg-num-s { display: -webkit-box; white-space: normal; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
  /* a page's own tabs — no name over them: on the line of the other cells' controls, under their names */
  .front-look .mb-f > .dl-cell.dl-mode:not(:has(> .dl-cell-l)) { justify-content: flex-end; }
}
#mn-nums .mn-sub-l { display: block; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
/* a note in a block: a row like the others — the line over it, none under it */
.front-look .mb-block > .tg-row { box-shadow: inset 0 1px 0 0 var(--zl); }
/* «Обзор»: the block of overdue bills — its head only, the number in the warning's colour */
.front-look .mn-overdue .pg-count .warn-txt { font-weight: var(--fw-semibold); }
/* «Что сделать»: the title and its sum on one line, the words under it, «Что сделать:» in the quiet ink */
.front-look .todo-head { display: flex; align-items: baseline; justify-content: space-between; gap: var(--sp-3); flex-wrap: wrap; }
.front-look .todo-sum { color: var(--ink-2); font-size: var(--fs-sm); font-variant-numeric: tabular-nums; white-space: nowrap; }
.front-look .todo-text { max-width: 80ch; color: var(--ink-2); font-size: var(--fs-sm); line-height: 20px; }
.front-look .todo-what { max-width: 80ch; color: var(--ink); font-size: var(--fs-sm); line-height: 20px; }
.front-look .todo-what-l { color: var(--ink-3); }
.front-look .todo-good .todo-title { color: var(--ok); }
.front-look .todo-why { max-width: 560px; margin-top: var(--sp-2); }
.front-look .todo-why td.num { white-space: nowrap; font-variant-numeric: tabular-nums; }
.front-look .todo-norm-f { display: flex; align-items: center; gap: var(--sp-3); min-width: 0; }
.front-look .todo-norm-f > .cell-input { width: 96px; }
/* «Сколько стоит бизнес»: the range the cell's big figure, the multiple's choice beside it */
.front-look .worth-range { color: var(--ink-2); font-size: var(--fs-sm); }
.front-look .worth-range b { color: var(--ink); font-size: 28px; font-weight: var(--fw-semibold); line-height: 34px; font-variant-numeric: tabular-nums; }
.front-look .worth-table td.num { white-space: nowrap; font-variant-numeric: tabular-nums; vertical-align: top; }
/* «Вопросы»: the kinds an iOS segmented control on a row of its own; the answers quieter than the keys that act — the
   name of an article, wrapped in its column */
.front-look .mq-kinds > .dl-cell { min-height: 56px; justify-content: center; }
.front-look .mq-kinds { box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mq-kinds > .dl-cell { box-shadow: none; }
.front-look .mn-q-acts > .dt-key { font-size: var(--fs-sm); font-weight: var(--fw-medium); }
.front-look .mn-q-none { display: flex; align-items: center; gap: var(--sp-2); }
.front-look .mn-q-purpose { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
/* a block's name with its icon (a place of money) */
.front-look .mb-block > .pg-head > h2 > svg { flex: none; margin-right: var(--sp-2); color: var(--ink-3); vertical-align: -3px; }
/* a head that sums its rows: how many in the name, the sums at the right, apart */
.front-look .pg-head.mn-sumbar > .pg-count { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 2px var(--sp-4); white-space: nowrap; }
/* a figure of the page's row (all the cash): its name small, the figure in the numbers' letters */
.front-look .dl-cell.mb-fig { justify-content: center; gap: 2px; }
.front-look .mb-fig-v { color: var(--ink); font-size: 22px; font-weight: var(--fw-semibold); line-height: 28px; font-variant-numeric: tabular-nums; }
/* «Кассы и сейфы»: a place's balance in its head; its rows' table in the five columns — the day, the sum, the article
   two, who — the same in every block */
@media (min-width: 701px) {
  .front-look .mn-cash table.mn-ops { table-layout: fixed; }
  .front-look .mn-cash table.mn-ops th:nth-child(1), .front-look .mn-cash table.mn-ops th:nth-child(2), .front-look .mn-cash table.mn-ops th:nth-child(4) { width: 20%; }
  .front-look .mn-cash table.mn-ops th:nth-child(3) { width: 40%; }
}
.front-look .mn-cash .pg-count .mn-bal { color: var(--ink); font-size: var(--fs-md); font-weight: var(--fw-semibold); }
/* a key that is on (a column of a file counted in the sum): the accent's shade, its words in the accent */
.front-look .mb-keys > .dt-key[aria-pressed='true'] { background: var(--accent-soft); color: var(--accent); }
.front-look .mb-keys > .dt-key[aria-pressed='true'] > svg { color: var(--accent); }
/* a head whose sums are many (the cards against the bank): they wrap under the name */
.front-look .pg-head.mn-sumbar-w { flex-wrap: wrap; row-gap: 4px; padding-block: var(--sp-2); }
.front-look .pg-head.mn-sumbar-w > span { white-space: normal; }
/* «Пришло по почте»: the file's icon before its name */
.front-look .mm-name { display: flex; align-items: center; gap: var(--sp-2); }
.front-look .mm-name > svg { flex: none; color: var(--ink-3); }

/* a narrower computer (a column 150–190 wide): a key's icon over its name, the name smaller — as the head's keys; the
   figures smaller, a sum of millions whole in its square */
@media (min-width: 701px) and (max-width: 1239px) {
  .front-look :is(.mb-row, .mb-keys) > .dt-key { flex-direction: column; gap: 2px; padding: var(--sp-2); font-size: var(--fs-sm); }
  /* (and a row of the page's choices: «Корректировка», «Загрузить отчёт», «Как в прошлом году» as the keys under it) */
  .front-look .dt-keys.mb-f > .dt-key { flex-direction: column; gap: 2px; padding: var(--sp-2); font-size: var(--fs-sm); }
  .front-look .rp-page > .card > .card-head > .btn { flex-direction: column; gap: 2px; padding: var(--sp-1) var(--sp-2); white-space: normal; font-size: var(--fs-sm); line-height: 18px; text-align: center; }
  #mn-nums .pg-num-v { font-size: 22px; line-height: 28px; }
}

@media (max-width: 700px) {
  /* an iOS segmented control on a phone: the whole row, its segments equal; a long name on two lines, no icon */
  :root .front-look .mb-f > .dl-mode > .seg.cs-tabs { display: grid; width: 100%; height: auto; min-height: 36px; grid-auto-columns: minmax(0, 1fr); }
  :root .front-look .mb-f > .dl-mode > .seg.cs-tabs > .seg-btn { min-width: 0; height: auto; min-height: 32px; padding: 4px 6px; white-space: normal; text-align: center; line-height: 15px; }
  :root .front-look .mb-f > .dl-mode > .seg.cs-tabs > .seg-btn > svg { display: none; }
  .front-look .mb-block > .dt-keys.dl-row.mb-f > :is(*, :first-child, :nth-child(5n + 1)) { box-shadow: inset 0 1px 0 0 var(--zl); }
  .front-look .mb-block > .dt-keys.dl-row.mb-f > .dt-key.acc:not(:disabled) { box-shadow: none; }
  /* (12 November, 11:07, the owner's screenshot of «Обзор»: «Загрузить» a third of the row, its other two thirds empty)
     a row's keys under its words share the row: one key the whole row, two a half each */
  .front-look .mb-item.mb-row { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .front-look .mb-row > .mb-w { grid-column: 1 / -1; }
  .front-look .mb-row > .mb-w + .dt-key:last-child { grid-column: 1 / -1; }
  .front-look .mb-w { padding: var(--sp-3) var(--sx, 16px); }
  .front-look .mb-keys { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .front-look .mb-row > .dt-key { box-shadow: var(--tl), inset 1px 0 0 0 var(--zl), var(--rim, 0 0 #0000); }
  .front-look .mb-row > .dt-key[data-rf] { box-shadow: var(--tl), var(--rim, 0 0 #0000); }
  .front-look .mb-row > .dt-key { --tl: inset 0 1px 0 0 var(--zl); }
  .front-look .mb-row > [data-rl] { --rim: 1px 0 0 0 var(--zl); }
  .front-look :is(.mb-row, .mb-keys) > .dt-key { flex-direction: column; gap: 2px; min-height: 64px; padding: var(--sp-2); font-size: var(--fs-sm); }
  /* a key with a long name: two of the three columns joined (its words are not cut at the square's edges) */
  .front-look .mb-keys > .dt-key.mb-long { grid-column: span 2; }
  /* «Деньги»' squares: the words under a figure two lines here too («кассы и сейфы» was «кассы и сей…») */
  :root .mn-app .pg-nums > .pg-num.ptable .pg-num-s:not(.pg-by) { display: -webkit-box; height: auto; max-height: 36px; white-space: normal; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
  .front-look .todo-head { flex-direction: column; gap: 2px; }
  .front-look .worth-range b { font-size: 24px; line-height: 30px; }
  .front-look .dl-cell.mb-fig { flex-direction: row; align-items: center; justify-content: space-between; }
  /* the rows of money as the waiter's rows: the day, the place and the sum on the first line, the article under them,
     whose and who under that */
  .front-look table.mn-ops, .front-look table.mn-ops > tbody { display: block; width: 100%; }
  .front-look table.mn-ops > thead { display: none; }
  .front-look table.mn-ops > tbody > tr {
    display: grid; grid-template-columns: auto minmax(0, 1fr) auto; grid-template-areas: 'day place sum' 'art art art' 'unit who who';
    column-gap: var(--sp-3); row-gap: 2px; padding: var(--sp-3) var(--sx, 16px); box-shadow: inset 0 -1px 0 0 var(--zl);
  }
  /* (stronger than the phone's tables that scroll sideways — 92-office-grid.css: the first column held, nothing wraps) */
  .front-look .table-wrap > table.tbl-data.mn-ops > tbody > tr > td:nth-child(n) {
    position: static; display: block; height: auto; min-width: 0; min-height: 0; max-width: none; padding: 0; border: 0; background: none; box-shadow: none; white-space: normal; line-height: 20px;
  }
  .front-look table.mn-ops > tbody > tr.mn-row-review { box-shadow: inset 3px 0 0 0 var(--warn), inset 0 -1px 0 0 var(--zl); }
  .front-look table.mn-ops td.c-day { grid-area: day; color: var(--ink-2); }
  .front-look table.mn-ops td.c-place { grid-area: place; overflow: hidden; color: var(--ink-2); text-overflow: ellipsis; }
  .front-look table.mn-ops td.c-sum { grid-area: sum; font-weight: var(--fw-semibold); }
  .front-look table.mn-ops td.c-art { grid-area: art; }
  .front-look table.mn-ops td.c-unit { grid-area: unit; font-size: var(--fs-sm); }
  .front-look table.mn-ops td.c-who { grid-area: who; font-size: var(--fs-sm); }
  .front-look table.mn-ops td.c-who:has(.mn-who > span:first-child:empty):not(:has(.small)) { display: none; }
  .front-look .pg-block > .table-wrap:has(> table.mn-ops) { overflow: visible; }
}

/* ---------- «Отчёт ресепшена» on the grid (ui/money-reception.jsx; 84-reception.css its old frame) ----------
   The day a row of the five — ‹, the day, its weekday, ›, what became of the report; a way of paying a block — its name
   and sum in the head; a payment a row — its number and who paid three columns, its sum, «убрать» —, its lines rows of
   the five — the room, what for, the sum, the note, «убрать»; «+ Строка» and «+ Оплата» keys of a column; the cash spent
   the same; the safe, the comment, the totals and «Отправить» rows; the last days a block with its table. */
.front-look .rp-page { gap: 0; }
.front-look .rp-page > .card { display: flex; flex-direction: column; gap: 0; margin: 0; padding: 0; border: 0; border-radius: 0; background: var(--surface); box-shadow: 0 1px 0 0 var(--zl); }
.front-look .rp-page > .card > .card-head { display: flex; align-items: center; gap: var(--sp-3); min-height: 56px; margin: 0; padding: 0 var(--px); box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .rp-page > .card > .card-head > h2 { display: flex; align-items: center; gap: var(--sp-2); margin: 0; font-size: var(--fs-md); font-weight: var(--fw-semibold); line-height: 22px; }
.front-look .rp-page > .card > .card-head > h2 > svg { color: var(--ink-3); }
.front-look .rp-page > .card > .card-head > .rp-sum { margin-left: auto; font-size: var(--fs-md); font-variant-numeric: tabular-nums; }
.front-look .rp-page > .card > .card-head > .btn { align-self: stretch; width: 20%; height: auto; min-height: 56px; margin: 0 calc(-1 * var(--px)) 0 auto; border: 0; border-radius: 0; box-shadow: inset 1px 0 0 0 var(--zl); }
/* the day */
.front-look .rp-daybar { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0; align-items: stretch; min-height: 56px; box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .rp-daybar > .grow { display: none; }
.front-look .rp-daybar > * { min-width: 0; }
.front-look .rp-daybar > .btn { height: auto; min-height: 56px; border: 0; border-radius: 0; background: var(--surface); box-shadow: inset 1px 0 0 0 var(--zl); }
.front-look .rp-daybar > .btn:first-child { box-shadow: none; }
.front-look .rp-daybar > .rp-day { display: flex; box-shadow: inset 1px 0 0 0 var(--zl); }
.front-look .rp-daybar > .rp-day > .select { flex: 1 1 auto; width: 100%; height: auto; min-height: 56px; padding: 0 var(--px); border: 0; border-radius: 0; background: var(--surface); box-shadow: inset 1px 0 0 0 var(--zl); }
.front-look .rp-daybar > .rp-wd { display: flex; align-items: center; padding: 0 var(--px); color: var(--ink-2); box-shadow: inset 1px 0 0 0 var(--zl); }
.front-look .rp-daybar > .rp-status, .front-look .rp-daybar > #rp-status { display: flex; flex-wrap: wrap; align-content: center; align-items: center; gap: 2px var(--sp-2); padding: var(--sp-2) var(--px); font-size: var(--fs-sm); box-shadow: inset 1px 0 0 0 var(--zl); }
.front-look .rp-page > .mn-note { margin: 0; padding: var(--sp-3) var(--px); border: 0; border-radius: 0; background: var(--surface); color: var(--warn); font-size: var(--fs-sm); box-shadow: none; }
/* (the visual audit, 11 November) under the note one line — the next block's head's: the note's own under it and the
   page's line over a block after words had made three */
.front-look .of-page.rp-page > .mn-note + .card { border-top: 0; }
/* the day's bar: its line under it drawn by its cells — the bar's own lay under their ground (it showed under the day and
   the weekday only) */
.front-look .rp-daybar > :is(.btn, .rp-day, .rp-wd, .rp-status) { box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
.front-look .rp-daybar > .btn:first-child { box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .rp-daybar > .rp-day > .select { box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
/* a payment and its lines */
.front-look .rp-pay { gap: 0; padding: 0; border: 0; box-shadow: none; }
.front-look .rp-pay-head, .front-look .rp-part { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); grid-template-areas: none; gap: 0; align-items: stretch; min-height: 52px; }
.front-look .rp-pay-head > .rp-pay-n { grid-row: 1; grid-column: 1; z-index: 1; align-self: center; margin-left: var(--px); }
.front-look .rp-pay-head > .rp-who { grid-row: 1; grid-column: 1 / span 3; padding-left: calc(var(--px) + 36px); }
.front-look .rp-pay-head > .rp-pay-sum { grid-row: 1; grid-column: 4; display: flex; align-items: center; justify-content: flex-end; padding: 0 var(--px); background: var(--surface); font-variant-numeric: tabular-nums; }
.front-look :is(.rp-pay-head, .rp-part) > .btn { grid-row: 1; grid-column: 5; height: auto; min-height: 52px; border: 0; border-radius: 0; background: var(--surface); color: var(--ink-2); }
.front-look :is(.rp-pay-head, .rp-part) > .btn:disabled { color: var(--ink-3); }
.front-look .rp-part { box-shadow: none; }
.front-look :is(.rp-pay-head, .rp-part) > * { box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl); }
.front-look .rp-part > :first-child, .front-look .rp-pay-head > .rp-who { box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .rp-pay-head > .rp-pay-n { box-shadow: none; }
.front-look :is(.rp-pay, .rp-part) input, .front-look .rp-part > .select {
  width: 100%; min-width: 0; height: auto; min-height: 52px; padding: 0 var(--px); border: 0; border-radius: 0; outline: 0; background: var(--surface); color: var(--ink); font: inherit; font-size: var(--fs-md);
}
.front-look :is(.rp-pay-head, .rp-part) > :is(input, .select):focus { outline: 0; box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl), inset 0 -2px 0 0 var(--accent); }
.front-look :is(.rp-pay-head, .rp-part) > input.bad { box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl), inset 0 -2px 0 0 var(--bad); }
.front-look .rp-part.rp-exp-row > .rp-unit { grid-column: 1 / -1; padding: 0 var(--px) var(--sp-2); }
/* «+ Строка», «+ Оплата», «+ Расход»: keys of a column at the row's start, the line round them */
.front-look .rp-page :is(.rp-addpart, .rp-addpay) { align-self: flex-start; width: 20%; height: auto; min-height: 52px; margin: 0; border: 0; border-radius: 0; background: var(--surface); color: var(--ink); box-shadow: inset 0 1px 0 0 var(--zl), 1px 0 0 0 var(--zl); }
.front-look .rp-page .rp-addpay { width: 40%; font-weight: var(--fw-semibold); }
.front-look .rp-page :is(.rp-addpart, .rp-addpay):hover { background: var(--surface-2); }
.front-look .rp-page .card > .rp-hint, .front-look .rp-page .card > p.muted, .front-look .rp-page .card > p.small { margin: 0; padding: var(--sp-3) var(--px); color: var(--ink-2); font-size: var(--fs-sm); box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .rp-page .card > p.mn-review-txt { color: var(--warn); }
.front-look .rp-page .card > p.bad-txt { color: var(--bad); }
/* the safe: «Сошлось» a row, the count a cell and the difference beside it */
.front-look .rp-safe > .rp-ok { margin: 0; padding: 0 var(--px); min-height: 52px; box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .rp-fact { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0; margin: 0; align-items: stretch; box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .rp-fact > .field { display: flex; flex-direction: column; justify-content: center; gap: 2px; margin: 0; padding: var(--sp-2) var(--px); }
.front-look .rp-fact > .field > input { height: 24px; min-height: 0; padding: 0; border: 0; border-radius: 0; background: transparent; text-align: left; }
.front-look .rp-fact > .rp-diff { display: flex; align-items: center; padding: 0 var(--px); box-shadow: inset 1px 0 0 0 var(--zl); }
/* the comment, the totals, how it goes and «Отправить» */
.front-look .rp-end { gap: 0; }
.front-look .rp-page .rp-end > .field { display: flex; flex-direction: column; gap: 2px; margin: 0; padding: var(--sp-2) var(--px); box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .rp-page .rp-end > .field > textarea { min-height: 48px; padding: 0; border: 0; border-radius: 0; background: transparent; box-shadow: none; }
.front-look .rp-page .rp-end > .field:focus-within { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -2px 0 0 var(--accent); }
.front-look .rp-end > .rp-totals, .front-look .rp-end > .rp-preview-box, .front-look .rp-end > p { margin: 0; padding: var(--sp-3) var(--px); box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .rp-end > .rp-preview-box .rp-preview { border-radius: 0; }
/* (the visual audit, 11 November) the message as it goes: a shade from edge to edge under its words — it had stood 16 px in
   from both sides */
.front-look .rp-end > .rp-preview-box[open] { padding-bottom: 0; }
.front-look .rp-end > .rp-preview-box .rp-preview { margin: var(--sp-3) calc(-1 * var(--px)) 0; padding: var(--sp-3) var(--px); box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .rp-page .rp-end > .row-gap { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0; margin: 0; box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .rp-page .rp-end > .row-gap > .btn { grid-column: 5; width: auto; height: auto; min-height: 56px; padding: var(--sp-2) var(--sp-3); border: 0; border-radius: 0; white-space: normal; line-height: 18px; }
.front-look .rp-end > .row-gap > .btn-primary { background: var(--accent); color: var(--accent-ink); box-shadow: none; }
/* (the form's ring of the old look's last row of keys had stayed round «Отправить» — over the row's line) */
.front-look #rp-send { box-shadow: none; }
.front-look .rp-end > .row-gap > .btn-primary:disabled { background: var(--surface-2); color: var(--ink-3); box-shadow: inset 1px 0 0 0 var(--zl); }
/* «Последние дни»: «Загрузить прошлые дни» a key at the head's end — a column of the five, the head's height (it had been a
   small framed button, off the columns) */
.front-look #rp-days > .card-head.mn-pad { align-items: stretch; min-height: 56px; padding-top: 0; padding-bottom: 0; padding-right: 0; }
.front-look #rp-days > .card-head.mn-pad > h2 { align-self: center; }
.front-look #rp-days > .card-head > #rp-import {
  flex: none; align-self: stretch; width: calc((100% + var(--px)) / 5); height: auto; min-height: 56px; margin: 0 0 0 auto; padding: 0 var(--sp-3); border: 0; border-radius: 0;
  background: var(--surface); color: var(--ink); font-size: var(--fs-md); font-weight: var(--fw-semibold); white-space: normal; line-height: 18px; box-shadow: inset 1px 0 0 0 var(--zl);
}
.front-look #rp-days > .card-head > #rp-import:hover { background: var(--surface-2); }
@media (min-width: 701px) and (max-width: 1239px) { .front-look #rp-days > .card-head > #rp-import { flex-direction: column; gap: 2px; font-size: var(--fs-sm); } }
@media (max-width: 700px) { .front-look #rp-days > .card-head > #rp-import { width: calc((100% + var(--px)) / 3); flex-direction: column; gap: 2px; font-size: var(--fs-sm); } }
.front-look #rp-days > p.muted { margin: 0; padding: var(--sp-3) var(--px); box-shadow: inset 0 1px 0 0 var(--zl); }
/* (the cards' bleed of the old look — a table and a last row pulled to the card's edges — undone: the blocks have none) */
.front-look .rp-page > .card:not(.flush) > :is(.table-wrap, .tbl-data), .front-look .rp-page > .card:not(.flush) > :is(.table-wrap, .tbl-data):last-child { margin: 0; }
.front-look .rp-page > section.card.rp-end > .row-gap:last-child { margin: 0; }

@media (max-width: 700px) {
  .front-look .rp-daybar { grid-template-columns: 56px minmax(0, 1fr) auto 56px; }
  .front-look .rp-daybar > :is(.rp-status, #rp-status) { grid-column: 1 / -1; box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .rp-pay-head, .front-look .rp-part { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .front-look .rp-pay-head > .rp-who { grid-column: 1 / span 2; }
  .front-look .rp-pay-head > .rp-pay-sum { grid-column: 3; }
  .front-look .rp-pay-head > .btn { grid-row: 2; grid-column: 3; box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl); }
  .front-look .rp-part { grid-template-areas: 'room kind kind' 'amt amt drop' 'note note note'; }
  .front-look .rp-part > .rp-room { grid-area: room; }
  .front-look .rp-part > .rp-kind { grid-area: kind; }
  .front-look .rp-part > .rp-amt { grid-area: amt; box-shadow: inset 0 1px 0 0 var(--zl); }
  .front-look .rp-part > .rp-note { grid-area: note; box-shadow: inset 0 1px 0 0 var(--zl); }
  .front-look .rp-part > .btn { grid-area: drop; box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl); }
  .front-look .rp-part.rp-exp-row { grid-template-areas: 'art art art' 'who amt drop' 'note note note'; }
  .front-look .rp-part.rp-exp-row > .rp-art { grid-area: art; }
  .front-look .rp-part.rp-exp-row > .rp-who { grid-area: who; box-shadow: inset 0 1px 0 0 var(--zl); }
  .front-look .rp-part.rp-exp-row > .rp-amt { grid-area: amt; box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl); }
  .front-look .rp-page :is(.rp-addpart, .rp-addpay) { width: calc(100% / 3); }
  .front-look .rp-page .rp-addpay { width: calc(200% / 3); }
  .front-look .rp-fact { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .front-look .rp-fact > .field { grid-column: span 2; }
  .front-look .rp-page > .card > .card-head > .btn { width: calc(100% / 3); flex-direction: column; gap: 2px; padding: var(--sp-1) var(--sp-2); white-space: normal; font-size: var(--fs-sm); line-height: 18px; text-align: center; }
  .front-look .rp-page .rp-end > .row-gap { grid-template-columns: minmax(0, 1fr); }
  .front-look .rp-page .rp-end > .row-gap > .btn { grid-column: 1; }
}

/* ---------- «Деньги», part 2 (11 November): P&L, «Бюджет» and «Коэффициенты» ---------- */
/* two keys at a block's head end (an unsaved change: «Отменить», «Сохранить»): side by side, a column each */
.front-look .mb-block > .pg-head > .pg-hkey:not(:last-child) { margin-right: 0; }
/* (the visual audit, 11 November: the head's own gap of 12 had stood between two keys — the first one's line 12 px off its
   column's) */
.front-look .mb-block > .pg-head > .pg-hkey + .pg-hkey { margin-left: calc(-1 * var(--sp-3)); }
.front-look .mb-block > .pg-head > .pg-hkey:disabled { color: var(--ink-3); cursor: default; }
.front-look .mb-block > .pg-head > .pg-hkey:disabled > svg { color: var(--ink-3); }
.front-look .mb-block > .pg-head > .pg-hkey.acc:disabled { background: var(--surface); color: var(--ink-3); box-shadow: inset 1px 0 0 0 var(--zl); }
/* P&L: the month's reports — cells of a row, each its sign and its words; a loaded one in the ink, its check green */
.front-look .mb-f > .pl-src { flex-direction: row; align-items: center; justify-content: flex-start; gap: var(--sp-2); color: var(--ink-2); }
.front-look .mb-f > .pl-src > svg { flex: none; color: var(--ink-3); }
.front-look .mb-f > .pl-src.on { color: var(--ink); }
.front-look .mb-f > .pl-src.on > svg { color: var(--ok); }
/* «Бюджет»: «План · Коэффициенты» where the other cells' controls stand — under their names' line, not at the row's foot:
   the row as high in both views, the tabs where they were (a computer's) */
@media (min-width: 701px) {
  .front-look .mb-f > .dl-cell.dl-mode.mb-tabs-low { justify-content: flex-start; padding-top: calc(var(--sp-3) + 18px + var(--sp-2)); }
}
/* «Коэффициенты» → the divided lines: a line its rows of the block — its name and how it is divided, the shares under */
.front-look .mb-block > .pl-split-row > .dt-keys.dl-row.mb-f > * { box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl); }
.front-look .mb-block > .pl-split-row > .dt-keys.dl-row.mb-f > :first-child { box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mb-block > .pl-split-row > .dt-keys.dl-row.mb-f > .dt-key.acc:not(:disabled) { box-shadow: none; }
.front-look .mb-block > .pl-split-row > .dt-keys.dl-row.mb-f > .dt-field:focus-within { box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl), inset 0 -2px 0 0 var(--accent); }
.front-look .mb-f > .pl-split-name { justify-content: center; gap: 2px; }
.front-look .mb-f > .pl-split-name > b { font-weight: var(--fw-semibold); line-height: 20px; }
.front-look .mb-f > .pl-split-sum.bad .mb-fig-v { color: var(--bad); }
.front-look .mb-f > .pl-split-u > input { font-variant-numeric: tabular-nums; }

/* ---------- a row of the page's choices on a phone (11 November, part 2) ---------- */
/* a day's short form (calendar.jsx, DateField short) — a phone's; a choice's phone list (MRow) — a phone's */
.df-short { display: none; }
.front-look .dt-keys.mb-f > .mb-seg-phone { display: none; }
@media (max-width: 700px) {
  /* three columns, as written (not the dishes' search first and accent key at the top): a list, a day, a field — a
     third of the row, half a square high (a control); two columns' cell — two thirds; a wider one and the search — the
     row (the words, the switches and the keys are rows of their own — 99-integr.css) */
  .front-look .dt-keys.mb-f > * { order: 0; }
  .front-look .dt-keys.mb-f > :is(.dt-pick, .dt-field, .dt-search) { aspect-ratio: auto; min-height: 64px; }
  .front-look .dt-keys.mb-f > .w2:is(.dt-pick, .dt-field) { grid-column: span 2; }
  .front-look .dt-keys.mb-f > :is(.w3, .w4, .w5):is(.dt-pick, .dt-field), .front-look .dt-keys.mb-f > .dt-search { grid-column: 1 / -1; }
  .front-look .dt-keys.mb-f > .dt-search { min-height: 56px; padding: 0 var(--sx, 16px); }
  /* a choice whose segments would not fit the row: its list */
  .front-look .dt-keys.mb-f > .mb-seg-wide { display: none; }
  .front-look .dt-keys.mb-f > .mb-seg-phone { display: grid; grid-column: 1 / -1; }
}

/* a day in a cell of a narrower screen (a computer's column under 1240 — «1 авг. 2026…» — and a phone's third): this
   year's day without its year */
@media (max-width: 1239px) {
  .front-look .mb-f .df-long { display: none; }
  .front-look .mb-f .df-short { display: inline; }
}

/* ---------- «Настройки» (13 November: «Для человека, который сталкивается в первый раз с системой — точно ничего не
   ясно») ----------
   «Статьи ДДС» and «Строки P&L» — tables of rows: a part («Поступления», «Выплаты») a head of the table's own words; a
   group (a section of P&L) a row that opens — its key the chevron and the name, how many after it — and says where it
   goes (where its figures come from); its rows under it, their names in a step from the group's, a line of P&L the
   further in the deeper; one switched off struck through. On a phone the second column goes under the name. */
.front-look .tbl-data.mn-sets-tbl tbody th { height: 44px; padding: var(--sp-1) var(--sp-3); background: none; color: var(--ink); font-size: var(--fs-md); font-weight: var(--fw-semibold); text-align: left;
  box-shadow: none; border-bottom: 1px solid var(--zl); }
.front-look .tbl-data.mn-sets-tbl tbody th:first-child { padding-left: var(--px); }
.front-look .tbl-data.mn-sets-tbl tr.mn-r-part > th { height: 52px; padding-top: var(--sp-4); vertical-align: bottom; color: var(--ink); font-size: var(--fs-lg, 17px); }
.front-look .tbl-data.mn-sets-tbl tr.mn-r-part > th > .muted { font-size: var(--fs-sm); font-weight: var(--fw-regular, 400); }
.front-look .tbl-data.mn-sets-tbl tr.mn-r-group > th .mn-toggle { gap: 6px; text-align: left; }
.front-look .tbl-data.mn-sets-tbl tr.mn-r-group > th .mn-toggle > svg { flex: none; color: var(--ink-2); }
.front-look .tbl-data.mn-sets-tbl tr.mn-r-group > th .mn-toggle .muted { font-weight: var(--fw-regular, 400); }
.front-look .tbl-data.mn-sets-tbl tr.mn-r-group:hover > * { background: var(--surface-2); }
.front-look .tbl-data.mn-sets-tbl tr.mn-r-group > th .mn-toggle:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 2px; }
/* a row's name a step in from its group's (the chevron and its gap: 16 + 6) — a line of P&L a step more for each group */
.front-look .tbl-data.mn-sets-tbl :is(tr.mn-art-row, tr.mn-pl-row) > td:first-child { padding-left: calc(var(--px) + 22px + var(--depth, 0) * 16px); }
.front-look .tbl-data.mn-sets-tbl tr.mn-pl-row.grp > td:first-child { font-weight: var(--fw-semibold); }
.front-look .tbl-data.mn-sets-tbl tr.off > td:first-child .mn-set-t { color: var(--ink-3); text-decoration: line-through; }
.front-look .tbl-data.mn-sets-tbl .mn-set-sub { display: none; }
.front-look .tbl-data.mn-sets-tbl th.num { width: 1%; white-space: nowrap; }
.front-look .tbl-data.mn-sets-tbl .mn-set-on { width: 1%; text-align: center; white-space: nowrap; }
.front-look .tbl-data.mn-sets-tbl td.mn-set-on > .switch { vertical-align: middle; }
/* (a block of «Деньги» closes itself with its line: a group's row last in it draws none of its own — 2 px had been there) */
.front-look .mb-block > .table-wrap:last-child > .tbl-data > tbody:last-child > tr:last-child > th { border-bottom-color: transparent; }
/* the two tables one under the other on the grid of the five: the name two columns, the line of P&L two, the rows of the
   year and the switch the fifth; where the figures come from — three */
@media (min-width: 701px) {
  .front-look .tbl-data.mn-sets-tbl:is(.mn-arts-tbl, .mn-pl-tbl) { table-layout: fixed; width: 100%; }
  .front-look .tbl-data.mn-sets-tbl:is(.mn-arts-tbl, .mn-pl-tbl) > thead th:first-child { width: 40%; }
  .front-look .tbl-data.mn-arts-tbl > thead th.mn-set-to { width: 40%; }
  .front-look .tbl-data.mn-arts-tbl > thead :is(th.num, th.mn-set-on) { width: 10%; }
  .front-look .tbl-data.mn-sets-tbl:is(.mn-arts-tbl, .mn-pl-tbl) .mn-set-to { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
}
@media (max-width: 700px) {
  .front-look .table-wrap > .tbl-data.mn-sets-tbl { min-width: 0; width: 100%; }
  .front-look .table-wrap > .tbl-data.mn-sets-tbl .mn-set-to { display: none; }
  .front-look .mn-settings .table-wrap > .tbl-data.mn-sets-tbl :is(th, td):first-child { position: static; max-width: none; white-space: normal; box-shadow: none; background: none; }
  .front-look .mn-settings .table-wrap > .tbl-data.mn-sets-tbl thead :is(th, td):first-child { background: var(--bg); }
  /* (their first column is not held at the left: no line at its right in the head either) */
  .front-look.mn-app .mn-settings .table-wrap > .tbl-data.mn-sets-tbl > thead > tr:first-child > th:first-child { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
  /* a place's kind, beginning and opening under its name — in a line with the name, after the icon */
  .front-look .tbl-data.mn-places-tbl .mn-set-sub { padding-left: calc(18px + var(--sp-2)); }
  .front-look .mn-settings .table-wrap > .tbl-data.mn-sets-tbl tr.clickable:hover td:first-child { background: var(--surface-2); }
  .front-look .tbl-data.mn-sets-tbl .mn-set-sub { display: block; margin-top: 2px; font-size: var(--fs-sm); font-weight: var(--fw-regular, 400); line-height: 18px; }
  .front-look .tbl-data.mn-sets-tbl tr.mn-r-group > th .mn-set-sub { padding-left: 22px; }
  .front-look .tbl-data.mn-sets-tbl :is(td, th) { height: auto; min-height: 44px; padding-top: var(--sp-2); padding-bottom: var(--sp-2); }
}
/* «ДДС = P&L»: what still gives «без разбивки» — a part of the block, its list under its words */
.front-look .mb-block > .pl-align-part { margin: 0; padding: var(--sp-3) var(--px); box-shadow: inset 0 1px 0 0 var(--zl); font-size: var(--fs-sm); }
.front-look .mb-block > .pl-align-part > p { margin: 0 0 var(--sp-2); color: var(--ink-2); }
.front-look .mb-block > .pl-align-part > .pl-align-list { margin: 0; }

/* ---------- «Подключения» (11 November) ---------- */
/* facts of a block: a row each — its name a column of the five, what it is the rest (a key at its end — its column) */
.front-look .mb-facts { margin: 0; padding: 0; list-style: none; }
.front-look .mb-fact { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); min-height: 48px; box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mb-fact > .mb-fact-l { align-self: center; padding: var(--sp-3) var(--px); color: var(--ink-2); font-size: var(--fs-sm); line-height: 18px; }
.front-look .mb-fact > .mb-fact-v { grid-column: span 4; align-self: center; min-width: 0; padding: var(--sp-3) var(--px); overflow-wrap: anywhere; line-height: 20px; }
.front-look .mb-fact.with-key > .mb-fact-v { grid-column: span 3; }
.front-look .mb-fact.with-keys2 > .mb-fact-v { grid-column: span 2; }
.front-look .mb-fact > .dt-key { min-height: 48px; box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl); white-space: normal; text-align: center; line-height: 18px; }
.front-look .mb-fact > .dt-key.bad { color: var(--bad); }
.front-look .mb-fact > .dt-key.acc { background: var(--accent); color: var(--accent-ink); box-shadow: none; }
.front-look .mb-fact > .mb-fact-v > :is(.select, .select-wrap) { max-width: 420px; }
/* a part of a block with its own head (Syrve's takings, P&L from Syrve): its words, its rows */
/* (none of the old card's own air and border — 81-money.css's .sy-takings and .sy-form had a margin, a border and a
   padding: a strip between two lines over «Выручка из Syrve»; the part's rows draw the lines over them) */
.front-look .mb-block > .mb-part, .front-look .mb-part > .mb-part { display: flex; flex-direction: column; gap: 0; margin: 0; padding: 0; border: 0; border-radius: 0; background: none; }
.front-look .mb-part > .dt-keys.dl-row.mb-f > * { box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl); }
.front-look .mb-part > .dt-keys.dl-row.mb-f > :first-child { box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mb-part > .dt-keys.dl-row.mb-f > .dt-key.acc:not(:disabled) { box-shadow: none; }
.front-look .mb-part > .dt-keys.dl-row.mb-f > :is(.dt-pick, .dt-field):focus-within { box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl), inset 0 -2px 0 0 var(--accent); }
.front-look .mb-part > .tg-row, .front-look .mb-part > .mb-list > .tg-row { box-shadow: inset 0 1px 0 0 var(--zl); }
/* (P&L from Syrve: its months rows of a list, a line over each, no air between them) */
.front-look .mb-part > .mb-list.sy-pl-months { gap: 0; }
.front-look .mb-part > .table-wrap { box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mb-part > :is(details.bf-group) > summary { display: flex; align-items: center; gap: var(--sp-2); min-height: 48px; padding: 0 var(--px); list-style: none; cursor: pointer; box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mb-part > details.bf-group > summary::-webkit-details-marker { display: none; }
.front-look .mb-part > details.bf-group > summary::before { content: ''; flex: none; width: 7px; height: 7px; margin-right: 4px; border: solid var(--ink-3); border-width: 0 1.5px 1.5px 0; transform: rotate(-45deg); transition: transform 0.15s; }
.front-look .mb-part > details.bf-group[open] > summary::before { transform: rotate(45deg); }
.front-look .mb-block > .tg-row, .front-look .mb-part > .tg-row { margin: 0; }
.front-look .mb-block > .dt-keys.dl-row.mb-f > .dt-key.bad { color: var(--bad); }
.front-look .pg-head > .pg-count.ok { color: var(--ok); }
.front-look .pg-head > .pg-count.bad { color: var(--bad); }
@media (max-width: 700px) {
  .front-look .mb-fact { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .front-look .mb-fact > .mb-fact-l { grid-column: 1 / -1; padding-bottom: 0; }
  .front-look .mb-fact > .mb-fact-v, .front-look .mb-fact.with-key > .mb-fact-v { grid-column: 1 / -1; padding-top: 2px; }
  .front-look .mb-fact > .dt-key { grid-column: 1 / -1; box-shadow: inset 0 1px 0 0 var(--zl); }
  .front-look .mb-part > .dt-keys.dl-row.mb-f > :is(*, :first-child) { box-shadow: inset 0 1px 0 0 var(--zl); }
}

/* ---------- «Счета» (11 November) ---------- */
/* a figure cell gone wrong (the overdue, the shares not adding up to 100 %): its figure in the bad colour */
.front-look .mb-f > .mb-fig.bad .mb-fig-v { color: var(--bad); }
/* «Без статьи»: a supplier — its words a row (a key to its bill), its article, whose, «Запомнить», «Сохранить» a row of
   the five under it */
.front-look .mb-block > .bl-review-row > .bl-review-who { display: flex; flex-direction: column; gap: 2px; width: 100%; min-height: 56px; padding: var(--sp-3) var(--px);
  border: 0; border-radius: 0; background: var(--surface); color: var(--ink); font: inherit; text-align: left; cursor: pointer; box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mb-block > .bl-review-row > .bl-review-who > b { font-weight: var(--fw-semibold); line-height: 20px; }
.front-look .mb-block > .bl-review-row > .bl-review-who:hover { background: var(--surface-2); }
.front-look .mb-block > .bl-review-row > .bl-review-who:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.front-look .mb-block > :is(.bl-review-row, .bf-plan) > .dt-keys.dl-row.mb-f > * { box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl); }
.front-look .mb-block > :is(.bl-review-row, .bf-plan) > .dt-keys.dl-row.mb-f > :first-child { box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mb-block > :is(.bl-review-row, .bf-plan) > .dt-keys.dl-row.mb-f > .dt-key.acc:not(:disabled) { box-shadow: none; }
.front-look .mb-block > .bl-review-row > .dt-keys.dl-row.mb-f > :is(.dt-pick, .dt-field):focus-within { box-shadow: inset 0 1px 0 0 var(--zl), inset 1px 0 0 0 var(--zl), inset 0 -2px 0 0 var(--accent); }
/* «Из файла»: what the server would do — its facts, then each kind of row folded under its row */
.front-look .mb-block > .bf-plan { display: flex; flex-direction: column; margin: 0; padding: 0; border: 0; border-radius: 0; background: none; }
.front-look .bf-plan > .mn-facts { display: flex; flex-direction: column; gap: 4px; margin: 0; padding: var(--sp-3) var(--px); list-style: none; box-shadow: inset 0 1px 0 0 var(--zl); font-size: var(--fs-sm); line-height: 20px; }
.front-look .bf-plan > .bf-group > summary { display: flex; align-items: center; gap: var(--sp-2); min-height: 48px; padding: 0 var(--px); list-style: none; cursor: pointer; box-shadow: inset 0 1px 0 0 var(--zl); }
