.front-look .bf-plan > .bf-group > summary::before { content: ''; flex: none; width: 7px; height: 7px; margin-right: 4px; border: solid var(--ink-3); border-width: 0 1.5px 1.5px 0; transform: rotate(-45deg); transition: transform 0.15s; }
.front-look .bf-plan > .bf-group[open] > summary::before { transform: rotate(45deg); }
