  .front-look .mb-block > :is(.bl-review-row, .bf-plan) > .dt-keys.dl-row.mb-f > :is(*, :first-child) { box-shadow: inset 0 1px 0 0 var(--zl); }
  .front-look .mb-block > .pl-split-row > .dt-keys.dl-row.mb-f > .dt-key.acc:not(:disabled) { box-shadow: none; }
}

/* ---------- «Зарплата» (11 November) ---------- */
