.front-look .mb-f > .dl-words.mb-ok { display: flex; flex-direction: row; align-items: center; gap: 6px; color: var(--ok); font-weight: var(--fw-semibold); }

/* (the visual audit, 11 November) a row of the page's choices right over its figures: its line under it is theirs over
   them — two had touched («Счета» → «Чьи» over the squares) */
@media (min-width: 701px) {
  .front-look .of-page > .dt-keys.mb-f:has(+ .pg-nums) > * { box-shadow: inset 1px 0 0 0 var(--zl); }
  .front-look .of-page > .dt-keys.mb-f:has(+ .pg-nums) > :is(:first-child, :nth-child(5n + 1)) { box-shadow: none; }
  .front-look .of-page > .dt-keys.mb-f:has(+ .pg-nums) > .dt-key.acc { box-shadow: none; }
}
@media (max-width: 700px) {
  /* (the visual audit, 11 November) a phone's head of two keys: the name a row of its own — squeezed out, it had vanished
     («Syrve — сервер ресторана»); under it what it counts and the two keys, a third each */
  .front-look .mb-block > .pg-head:has(> .pg-hkey + .pg-hkey) { flex-wrap: wrap; gap: 0; padding-right: 0; }
  .front-look .mb-block > .pg-head:has(> .pg-hkey + .pg-hkey) > h2 { flex: 1 0 100%; min-height: 56px; display: flex; align-items: center; }
  .front-look .mb-block > .pg-head:has(> .pg-hkey + .pg-hkey) > .pg-count { display: flex; flex: none; align-items: center; align-self: stretch; width: calc((100% + var(--px)) / 3); min-height: 56px; margin: 0 0 0 calc(-1 * var(--px)); padding: 0 var(--px); box-shadow: inset 0 1px 0 0 var(--zl); }
  .front-look .mb-block > .pg-head:has(> .pg-hkey + .pg-hkey) > .pg-hkey { width: calc((100% + var(--px)) / 3); min-height: 56px; margin: 0; }
  .front-look .mb-block > .pg-head:has(> .pg-hkey + .pg-hkey) > .pg-hkey:first-of-type { margin-left: auto; }
  .front-look .mb-block > .pg-head:has(> .pg-hkey + .pg-hkey) > .pg-hkey:not(.acc) { box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl); }
  /* a row of the page's choices right over the figures: its last cell's line under it is theirs over them */
  .front-look .of-page > .dt-keys.mb-f:has(+ .pg-nums) > :last-child { box-shadow: none; }
}

/* (12 November, the deep visual audit of «Деньги»: ДДС and P&L — the articles' column darker than its rows, an edge
   without a line) a row's own head (th of the body) wears the row's surface, not the table head's ground */
.front-look .tbl-data tbody th.mn-stick { background: var(--surface); }
.front-look .tbl-data tbody tr.mn-r-section > th.mn-stick { background: var(--surface-2); }
/* (the same audit) the sum's bar over a list («5 строк · Поступления … Выплаты»): its old line under it — of another
   shade — and the table's head's over itself were two; the head's is the one */
.front-look .pg-head.mn-sumbar { border-bottom: 0; }
/* a block of «Деньги» closes itself with its line under it: the last row's head (ДДС's «Остаток на конец») draws none of
   its own, as its cells don't — a line of 2 px had been under the articles' column */
.front-look .mb-block > .table-wrap:last-child > .tbl-data > tbody:last-child > tr:last-child > th,
.front-look .mb-block > .tbl-data:last-child > tbody:last-child > tr:last-child > th { box-shadow: none; }
/* the page's first block («Подключения» → Syrve) draws the line under its head itself: its first fact none over itself */
.front-look .of-page > .of-head + .pg-block > .pg-head:first-child + .mb-facts > .mb-fact:first-child { box-shadow: none; }
.front-look .of-page > .of-head + .pg-block > .pg-head:first-child + .mb-facts > .mb-fact:first-child > .dt-key:not(.acc) { box-shadow: inset 1px 0 0 0 var(--zl); }
/* «Деньги»' rows draw the line over themselves — a table's head too, whatever stands over it (a note, a row of keys, a
   file's row, a card's head): its ground met theirs with no line (the deep visual audit, 12 November); a table that opens
   a sheet's body stands on the head's line and draws none over itself */
.front-look.mn-app .tbl-data > thead > tr:first-child > th { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
.front-look.mn-app .sheet-body > .table-wrap:first-child > .tbl-data > thead > tr:first-child > th,
.front-look.mn-app .sheet-body > .tbl-data:first-child > thead > tr:first-child > th { box-shadow: inset 0 -1px 0 0 var(--zl); }
/* «Отчёт ресепшена» (the deep visual audit, 12 November): a payment's parts one under another — the grid's lines, not the
   old look's dashed one between them; «+ Строка», «+ Оплата», «+ Расход» a row of the form each, its whole width (a key
   a fifth or a third of a row, the rest of it empty, looked dropped — as «Обзор»'s «Загрузить») */
.front-look .rp-part + .rp-part { padding-top: 0; border-top: 0; }
.front-look .rp-page :is(.rp-addpart, .rp-addpay), .front-look .rp-page .rp-addpay { align-self: stretch; width: 100%; box-shadow: inset 0 1px 0 0 var(--zl); }
/* «Вопросы»: the kinds' row over the questions — its cell's line under it and the first question's over itself were two;
   the question's is the one (rows draw the line over themselves) */
.front-look .dt-keys.mq-kinds > .dl-cell.dl-mode { box-shadow: none; }
/* a phone's list as the last of a block (Операции, Банк, Кассы): its last row's line under it and the block's own closing
   line were two — the block's is the one */
@media (max-width: 700px) {
  .front-look .mb-block > .table-wrap:last-child > .tbl-data > tbody:last-child > tr:last-child { box-shadow: none; }
  .front-look .mb-block > .table-wrap:last-child > table.mn-ops > tbody:last-child > tr.mn-row-review:last-child { box-shadow: inset 3px 0 0 0 var(--warn); }
}
/* a phone: the table's first column holds its place as the rest scrolls (its line at its right) — its head's cell draws
   the line over itself too, as the other heads' cells (the page's first block under its head: its own line, none) */
@media (max-width: 700px) {
  .front-look.mn-app .table-wrap > .tbl-data:not(.list-rows) > thead > tr:first-child > th:first-child { box-shadow: inset -1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
  .front-look.mn-app .of-page > .of-head + .pg-block > .pg-head:first-child + .table-wrap > .tbl-data > thead > tr:first-child > th:first-child,
  .front-look.mn-app .sheet-body > .table-wrap:first-child > .tbl-data > thead > tr:first-child > th:first-child { box-shadow: inset -1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
}
/* «Наличные траты» read from a file: its tables from the card's edge to its edge, as every table of a card — they had
   stopped at its margins, their heads' ground ending with no line */
.front-look.mn-app .co-look > .co-block > .table-wrap { margin-inline: calc(-1 * var(--sx, var(--sp-5))); }
.front-look.mn-app .co-look > .co-block > .table-wrap > .tbl-data :is(th, td):first-child { padding-left: var(--sx, var(--sp-5)); }
.front-look.mn-app .co-look > .co-block > .table-wrap > .tbl-data :is(th, td):last-child { padding-right: var(--sx, var(--sp-5)); }
/* «Коэффициенты»: the year's column a shade apart — the grid's lines at both its sides (the old look's own line of another
   shade at its right only, none at its left) */
.front-look .pl-coef-table td.pl-coef-year { border-right: 0; box-shadow: inset 1px 0 0 0 var(--zl), inset -1px 0 0 0 var(--zl); }
.front-look .pl-coef-table th.pl-coef-year { border-right: 0; box-shadow: inset 1px 0 0 0 var(--zl), inset -1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
/* a block of «Деньги» after one that ends with a table: its head draws its line over itself. (The back office's lists keep
   their last row's line and the next head drops its own; «Деньги»' block closes itself with a line outside it instead,
   which the next block's ground covers — the two ways together had left no line at all between «Коэффициенты»' blocks) */
.front-look .mb-block:has(> .table-wrap:last-child > .tbl-data > tbody:last-child) + .mb-block > .pg-head:first-child,
.front-look .mb-block:has(> .tbl-data:last-child > tbody:last-child) + .mb-block > .pg-head:first-child { box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .mb-block:has(> .table-wrap:last-child > .tbl-data > tbody:last-child) + .mb-block > .pg-head:first-child > .pg-hkey:not(.acc),
.front-look .mb-block:has(> .tbl-data:last-child > tbody:last-child) + .mb-block > .pg-head:first-child > .pg-hkey:not(.acc) { box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl); }
/* a statement's lines, then the row of its balances and «Загрузить»: the row draws the line over itself — the table's
   last row none under it (2 px had been there) */
.front-look.mn-app .table-wrap:has(+ .dt-keys) > .tbl-data > tbody:last-child > tr:last-child > td { border-bottom-color: transparent; }
@media (max-width: 700px) {
  /* «Коэффициенты» on a phone: the articles' column holds its place with its line at its right — the year's column right
     after it draws none at its left (2 px) */
  .front-look .pl-coef-table :is(th, td):first-child + td.pl-coef-year { box-shadow: inset -1px 0 0 0 var(--zl); }
  .front-look .pl-coef-table :is(th, td):first-child + th.pl-coef-year { box-shadow: inset -1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
  /* «График смен», «Расчёт»: the month a row of the head — the arrows at its ends, the month between, the screen's width
     (it had stopped after the arrow, the rest of the row empty, the arrow on a ground of its own) */
  .front-look.mn-app .of-head > .of-actions > .sc-week.pr-month { display: grid; flex: 1 1 100%; grid-column: 1 / -1; grid-template-columns: 56px minmax(0, 1fr) 56px; align-items: stretch; gap: 0; min-height: 56px; }
  .front-look.mn-app .of-head > .of-actions > .sc-week.pr-month > .icon-btn { width: auto; height: auto; min-height: 56px; border: 0; border-radius: 0; background: none; }
  .front-look.mn-app .of-head > .of-actions > .sc-week.pr-month > .icon-btn:first-child { box-shadow: inset -1px 0 0 0 var(--zl); }
  .front-look.mn-app .of-head > .of-actions > .sc-week.pr-month > .icon-btn:last-child { box-shadow: inset 1px 0 0 0 var(--zl); }
  .front-look.mn-app .of-head > .of-actions > .sc-week.pr-month > .sc-week-t { align-items: center; justify-content: center; padding: 0; }
  /* «Выручка»: «Чья выручка» a row of the screen's width, as the choices over it (it was a third of a row, the rest empty) */
  .front-look #pos-keys > .dt-pick { grid-column: 1 / -1; }
}
/* a place's card: what can be done with the place (merge it, delete it) under its switch — words of the card, not a part
   of the old look with its own line and a strip over it */
.front-look .sheet-body > .mn-merge { margin-top: 0; padding-top: 0; border-top: 0; }
@media (max-width: 700px) {
  /* the first column of a table holds its place on a phone, its width at most half the screen: a long word in it (an
     account's number) breaks at the column's edge, not over the next column's words */
  /* (13 November, the owner's iPhone: «можно ли сделать более читаемым раздел денег с телефона?» — the first column of
     ДДС, P&L and the budget had come to two letters a line: «Остат-ок на на-чало») it breaks by words, never by letters
     (an account's number keeps breaking anywhere — .mn-place-acc); the statements' articles and lines take nearly half
     of the screen, the months beside them go sideways */
  .front-look.mn-app .table-wrap > .tbl-data:not(.list-rows) :is(th, td):first-child { overflow-wrap: break-word; }
  .front-look.mn-app .table-wrap > .tbl-data.mn-report:not(.list-rows) :is(th, td):first-child { min-width: 44vw; }
  /* (13 November, «Делай так») one month on a phone — ДДС and P&L: the table is the screen's width, the names take what
     the sums leave them, the sums keep to one line; nothing goes sideways */
  .front-look.mn-app .table-wrap > .tbl-data.mn-report.mn-one:not(.list-rows) { width: 100%; }
  .front-look.mn-app .table-wrap > .tbl-data.mn-report.mn-one:not(.list-rows) :is(th, td):first-child { width: 100%; min-width: 0; max-width: none; }
  /* nothing scrolls under the names: they are not held at the left — a row's line runs under its name too, a section's
     ground under its name too, and no line stands between the name and its sum (as on a computer) */
  .front-look.mn-app .table-wrap > .tbl-data.mn-report.mn-one:not(.list-rows) > tbody > tr > :first-child { position: static; background: none; box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look.mn-app .table-wrap > .tbl-data.mn-report.mn-one:not(.list-rows) > tbody > tr.mn-r-section > :first-child { background: var(--surface-2); }
  /* (the block's own line closes the last row — the name's would have stood over it, 2 px under the name, 1 under the sum) */
  .front-look.mn-app .mb-block > .table-wrap:last-child > .tbl-data.mn-report.mn-one:not(.list-rows) > tbody:last-child > tr:last-child > :first-child { box-shadow: none; }
  .front-look.mn-app .table-wrap > .tbl-data.mn-report.mn-one:not(.list-rows) > thead > tr:first-child > th:first-child { position: static; box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
  .front-look.mn-app .mn-place-acc { white-space: normal; overflow-wrap: anywhere; }
}
/* a computer's card of «Деньги» is a rounded window: a field's choice in it the iOS pill's track (the owner, 10 November:
   rounded windows have rounded things in them) — not the phone's strip of cells, which had come out half one, half the
   other (square cells, a rounded chosen one) */
@media (min-width: 701px) {
  :root .front-look.mn-app .sheet .field > .seg {
    display: inline-grid; align-self: flex-start; grid-auto-flow: column; grid-auto-columns: minmax(max-content, 1fr); align-items: center; gap: 2px; width: auto; height: 36px; min-height: 36px;
    max-width: 100%; margin: var(--sp-1) 0 0; padding: 2px; overflow: visible; border: 0; border-radius: var(--r-pill); background: var(--seg-track); box-shadow: none;
  }
  :root .front-look.mn-app .sheet .field > .seg > .seg-btn:nth-child(n) {
    display: inline-flex; align-items: center; justify-content: center; gap: 4px; height: 32px; min-height: 32px; padding: 0 var(--sp-3); border: 0; border-radius: var(--r-pill);
    background: none; box-shadow: none; color: var(--ink); font-size: 13px; font-weight: var(--fw-medium); line-height: 1; white-space: nowrap;
  }
  :root .front-look.mn-app .sheet .field > .seg > .seg-btn.on:nth-child(n) { background: var(--seg-on); color: var(--ink); box-shadow: 0 1px 3px rgb(0 0 0 / 0.14), 0 0 0 0.5px rgb(0 0 0 / 0.05); font-weight: var(--fw-semibold); }
}
/* a key that cannot be pressed yet (13 November, the owner: «Делаем» — «Сохранить» of «Бюджет», «Закрыть месяц», a
   token's «Сохранить»): a cell of its row as the others — their ground, its words dimmed, the row's lines round it; not
   the accent's grey block with no lines of its own. (The accent's fill is for a key that does something now.) */
:root:root .front-look :is(.dt-key, .pg-hkey).acc:disabled { background: var(--surface); color: var(--ink-3); cursor: default; }
:root:root .front-look :is(.dt-key, .pg-hkey).acc:disabled > svg { color: var(--ink-3); }

/* «Номенклатура» in «Блюда»' look (11 November, 02:39 — 02:44, the owner: «Визуал ингредиентов, полуфабрикатов и
   модификаторов повторяем с блюд»; ui/office-nomen.jsx). The keys' row: the search two of the five columns, the page's two
   keys, the new one the accent's; a phone — the search and the new one, then the two keys, the first of them two columns
   joined (three to a row: two only when two are one). The lists the dishes' tree; no station's band — a product has
   none —, the chosen row's band the accent's. */
.nm-keys > .dt-search { grid-column: span 2; }
.nm-keys > .dt-key > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
@media (max-width: 700px) {
  .nm-keys > .dt-search + .dt-key { grid-column: span 2; aspect-ratio: 4 / 1; flex-direction: row; gap: var(--sp-2); font-size: var(--fs-md); line-height: 20px; box-shadow: inset 0 -1px 0 0 var(--zl); }
  .nm-keys > .dt-search + .dt-key > svg { width: 18px; height: 18px; }
}

/* the tree: a group a row (its chevron, its name, how many), its products under it a little in; a list without groups its
   rows at the edge */
.nm-tree td.dt-name::before { background: transparent; }
.nm-tree tr.dt-dish.on td.dt-name::before { background: var(--accent); opacity: 1; }
.front-look .nm-tree tr.dt-dish > td.dt-name { padding-left: calc(var(--px) + 30px); }
.front-look .nm-tree tr.dt-dish.flat > td.dt-name { padding-left: var(--px); }
@media (min-width: 641px) {
  .nm-tree th.c-unit { width: 64px; }
  .nm-tree th.c-n { width: clamp(92px, 8vw, 128px); }
  .nm-tree th.c-req { width: clamp(120px, 11vw, 168px); }
  .nm-tree th.c-where { width: 26%; }
  .nm-tree td.c-where { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .nm-tree td.c-unit { color: var(--ink-2); }
}
/* (11 November, «пилюли — очень аккуратно») a row's state a quiet word after its name, no pill: new — the accent's,
   changed and hidden — the third ink's */
.front-look .dish-tree .st { padding: 0; border-radius: 0; background: none; box-shadow: none; color: var(--ink-3); font-size: var(--fs-sm); font-weight: var(--fw-regular); }
.front-look .dish-tree .st.st-draft { color: var(--accent); }
.nm-none { box-shadow: inset 0 -1px 0 0 var(--zl); }

/* the panel's tables: a dish's row opens its recipe — the chevron at its right */
.nm-used th.c-go, .nm-used td.c-go { width: 44px; padding-left: 0; padding-right: var(--px); color: var(--ink-3); text-align: right; }
.nm-used td.c-go > svg { vertical-align: middle; }
.front-look .nm-lines tfoot td { height: 52px; background: color-mix(in oklab, var(--ink) 4%, transparent); color: var(--ink); font-weight: var(--fw-semibold); }
/* an option's surcharge typed in its row */
.nm-opts th.c-price { width: clamp(120px, 11vw, 160px); }
.front-look .nm-opts td.c-price > .cell-input { width: 100%; max-width: 120px; text-align: right; }

/* «Блюда» of a group: a switch each — on a computer cells of the panel's five columns (a line at each one's left but the
   row's first, a line under each), a folder a row across them; a phone: the rows from edge to edge */
.nm-sws { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); margin-bottom: -1px; }
.nm-sw-cat { grid-column: 1 / -1; display: flex; align-items: center; min-height: 44px; padding: 0 var(--px); color: var(--ink-2); font-size: var(--fs-sm); font-weight: var(--fw-semibold); box-shadow: inset 0 -1px 0 0 var(--zl); }
.nm-sw-cat .dt-n { margin-left: var(--sp-2); font-weight: var(--fw-regular); }
.nm-sw { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-2); min-width: 0; min-height: 56px; padding: 0 var(--sp-3) 0 var(--px);
  color: var(--ink-2); font-size: var(--fs-sm); line-height: 18px; cursor: pointer; box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
.nm-sw.c1 { box-shadow: inset 0 -1px 0 0 var(--zl); }
