  .front-look :is(.card.tech-editor, .tech-bare) > .muted.pad-b { margin: 0; padding: var(--sp-3) 0 var(--sp-4); color: var(--ink-2); font-size: var(--fs-sm); line-height: 20px; }
  .front-look .card.tech-editor > .card-head + .muted.pad-b { padding-top: 0; }
  .front-look :is(.card.tech-editor, .tech-bare) > .lines-bar { flex-direction: column; flex-wrap: nowrap; align-items: stretch; min-height: 0; box-shadow: none; }
  .front-look :is(.card.tech-editor, .tech-bare) > .lines-bar > .lines-add { min-height: var(--cell-h, 56px); box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
  .front-look :is(.card.tech-editor, .tech-bare) > .table-wrap + .lines-bar > .lines-add { box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look :is(.card.tech-editor, .tech-bare) > .lines-bar > .lines-sum { justify-content: space-between; min-height: var(--cell-h, 56px); box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look :is(.card.tech-editor, .tech-bare) > .tech-actions { grid-template-columns: repeat(3, minmax(0, 1fr)); align-items: stretch; margin-top: 0; box-shadow: none; }
  .front-look .tech-bare { padding-bottom: 0; }
  :root .front-look :is(.card.tech-editor, .tech-bare) > .tech-actions > * { min-height: calc(100vw / 6); aspect-ratio: auto; }
  :root .front-look .tech-actions > .tech-state { grid-column: 1 / -2; box-shadow: inset 0 -1px 0 0 var(--zl); }
