.front-look :is(.cs-table, .voids-table) tr.dt-panel-row > td { height: auto; padding: 0; overflow: visible; white-space: normal; background: var(--surface-2); border-bottom: 1px solid var(--line-2); }
:is(.cs-table, .voids-table) tr.dt-panel-row:hover > td { background: var(--surface-2); }
.voids-table .vd-waste { margin-left: 0; }
/* the shift's panel on the second surface, the accent's band from its row to its end; its squares and sections on it */
.cs-panel-row .cs-panel { position: relative; background: var(--surface-2); }
.cs-panel-row .cs-panel::before { content: ''; position: absolute; z-index: 2; left: 0; top: 0; bottom: 0; width: 4px; background: var(--accent); pointer-events: none; }
.cs-panel-row .cs-panel :is(.ptable, .tbl-data th, .tbl-data td, .cs-sec) { background: transparent; }
.cs-panel-row .cs-panel .tbl-data th { background: color-mix(in oklab, var(--ink) 4%, transparent); }
.cs-panel-row .cs-panel .pg-num.pg-warn { background: var(--warn-soft); }
.cs-panel-row .cs-panel :is(.cs-bills, .cs-stock) tfoot td { background: color-mix(in oklab, var(--ink) 4%, transparent); }
/* (the tabs' line is the squares' top line) */
.cs-panel > .cs-p-tabs:has(+ .cs-main) { box-shadow: none; }
/* the drawer's and the expenses' rows: their lines from edge to edge of their section, the words in its margin */
.cs-sec > .cash-rows { margin: 0 calc(-1 * var(--px)); }
.cs-sec .cash-rows .cash-row { padding-left: var(--px); padding-right: var(--px); }
.cs-main-grid .cs-sec:is(.sp4, .sp5) > .cash-rows { column-gap: 0; }
/* (the visual audit of the lines, 12 November) the drawer in two columns: a line under each row — a line over each had
   hung one at the second column's top, over nothing */
.cs-main-grid .cs-sec:is(.sp4, .sp5) > .cash-rows > .cash-row { box-shadow: inset 0 -1px 0 0 var(--line-2); }
@media (max-width: 700px) {
  /* (a row's name on a phone: the shift and its day in the letters of a row, not of the figures) */
  .cs-table td.cs-no { font-family: var(--font-ui); letter-spacing: 0; }
}
/* (pills only for the tabs and the sheet's main key) a refund's and a cancelled dish's word — red, quiet, no pill */
.cs-ref-tag { height: auto; padding: 0; border-radius: 0; background: none; font-size: var(--fs-sm); font-weight: var(--fw-regular); }
/* (the visual audit: the band's sections a pixel left of the squares' lines over them — the panel under its row has no
   pixel to make up) */
.cs-panel-row .cs-main-grid { margin-left: 0; }
/* a narrower computer: a panel's square names in the small letters, two lines where they need them */
@media (min-width: 701px) and (max-width: 1239px) {
