.front-look .sef-loc > .check-row { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-3); min-height: 52px; margin: var(--sp-2) calc(-1 * var(--edge)) -10px; padding: 0 var(--edge); border: 0; box-shadow: inset 0 1px 0 0 var(--zl); }
