.front-look :is(.scan-pick, .scan-recent) .st.st-warn { color: var(--warn); }
.front-look :is(.scan-pick, .scan-recent) .st.st-bad { color: var(--bad); }
.front-look :is(.scan-pick, .scan-recent) .st.st-draft { color: var(--accent); }
.front-look .scan-pick .scan-recent-list { margin: 0 calc(-1 * var(--edge)); border-top: 0; box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .scan-pick .scan-recent-row { padding-left: var(--edge); padding-right: var(--edge); }
/* the list's columns: the invoice's number and day with its company on two lines at most */
