  .front-look .sef-bar > .select.sef-firm .select-icon { display: none; }
  .front-look .sef-bar > .select.sef-firm { padding: 0 var(--sx, 16px); font-size: var(--fs-sm); }
}
/* (the papers' words on the sheet's margin; a photo's restaurant a rounded field as the lines') */
.front-look .scan-cards > .scan-card { padding: var(--sp-4) var(--edge); }
.front-look .scan-draft .sef-facts .select { height: 40px; border: 0; border-radius: 10px; background: var(--surface-2); box-shadow: none; }
