  .front-look .loc-card.dl-row > .loc-who { grid-column: 1 / -1; flex-direction: column; align-items: flex-start; justify-content: center; min-height: 52px; padding: var(--sp-2) var(--sx, 16px); background: var(--surface-2); box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .loc-card > .loc-dl > :is(div, .w2) { grid-column: 1 / -1; display: flex; flex-direction: row; align-items: center; justify-content: space-between; gap: var(--sp-3); min-height: 52px; padding: var(--sp-2) var(--sx, 16px); box-shadow: inset 0 -1px 0 0 var(--zl); }
