  .front-look :is(.day-keys, .cur-keys) > .dt-pick { grid-column: 1 / -1; aspect-ratio: auto; min-height: 52px; box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look :is(.day-keys, .cur-keys) > .dt-pick > .dt-pick-l { align-self: center; justify-self: start; margin: 0 0 0 var(--sx, 16px); color: var(--ink); font-size: var(--fs-md); line-height: 22px; }
  :root .front-look :is(.day-keys, .cur-keys) > .dt-pick > .select { align-items: center; justify-content: flex-end; min-height: 52px; padding: 0 var(--sx, 16px) 0 50%; color: var(--ink-2); }
  :root .front-look :is(.day-keys, .cur-keys) > .dt-pick > .select .select-value { flex: 0 1 auto; text-align: right; }
  .front-look .dt-keys.dl-row > .dl-cell.dl-words { grid-column: 1 / -1; display: block; min-height: 0; padding: var(--sp-3) var(--sx, 16px); }
  .front-look .dt-keys.cur-keys > .dl-cell.dl-mode { flex-direction: column; align-items: flex-start; gap: var(--sp-2); padding-block: var(--sp-3); }
  .front-look .dt-keys.cur-keys > .dl-cell.dl-mode > .dl-cell-l { color: var(--ink); font-size: var(--fs-md); line-height: 22px; }
  .front-look .fc-norm-keys > .dl-form > .dt-field { grid-column: 1 / -1; flex-direction: row; align-items: center; gap: var(--sp-3); aspect-ratio: auto; min-height: 52px; padding: 0 var(--sx, 16px); box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .fc-norm-keys > .dl-form > .dt-field > .dt-field-l { flex: 1 1 auto; color: var(--ink); font-size: var(--fs-md); line-height: 22px; white-space: normal; }
  .front-look .fc-norm-keys > .dl-form > .dt-field > input { flex: none; width: 64px; height: 50px; color: var(--ink-2); text-align: right; }
  /* the firms: a firm's cells rows, its two keys a row of their own — «Изменить» a third, the SEF's two */
  .front-look .firm-row.dl-row > :is(.firm-who, .firm-locs-cell, .firm-sef) { grid-column: 1 / -1; }
  .front-look .firm-row.dl-row > .firm-who { flex-direction: column; align-items: flex-start; min-height: 52px; padding: var(--sp-2) var(--sx, 16px); background: var(--surface-2); }
  .front-look .firm-row.dl-row > :is(.firm-locs-cell, .firm-sef) { flex-direction: column; align-items: flex-start; gap: 2px; }
  .front-look .firm-row.dl-row > .dt-key { grid-column: span 1; aspect-ratio: auto; min-height: 52px; flex-direction: row; font-size: var(--fs-md); }
  .front-look .firm-row.dl-row > .dt-key + .dt-key { grid-column: span 2; box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
  .front-look .firm-none.dl-row > :is(.dl-words, .dt-key) { grid-column: 1 / -1; }
  .front-look .firm-none > .dt-key { flex-direction: row; aspect-ratio: auto; min-height: 52px; font-size: var(--fs-md); }
  /* the devices: a restaurant's row its name two columns, «Подключить» the third; a device its name and line a row,
     its keys a row under it — a third each, or the last one on to the row's end */
  .front-look .dev-table tr { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  /* (the phone's older rules of this list — a flex row with a gap, its cells placed by number — out) */
  .front-look .dev-table tr, .front-look .dev-table tr:is(.dev-loc, .dev-row) { display: grid; gap: 0; padding: 0; align-items: stretch; }
  .front-look .dev-table tr:is(.dev-loc, .dev-row) > :is(th, td) { grid-row: auto; text-align: left; }
  .front-look .dev-table tr > :is(th, td) { min-height: 52px; }
  .front-look .dev-table tr.dev-loc > th { grid-column: span 2; flex-direction: column; align-items: flex-start; justify-content: center; padding-inline: var(--sx, 16px); }
  .front-look .dev-table tr.dev-loc > th[colspan="5"] { grid-column: 1 / -1; }
  .front-look .dev-loc-n::before { content: none; }
  .front-look .dev-table tr.dev-row > td.dev-who { grid-column: span 2; padding-inline: var(--sx, 16px); }
  .front-look .dev-table tr.dev-row > td.dev-line { grid-column: span 1; padding-inline: var(--sp-3) var(--sx, 16px); }
  .front-look .dev-table tr.dev-row > td.dev-k { grid-column: span 1; }
