  .front-look .dev-table td.dev-k > .dt-key { flex-direction: row; gap: 6px; padding: 0 var(--sp-2); font-size: var(--fs-sm); }
  /* the demo's data: its line a row, its two keys a row — the filling two columns, the clearing one */
  .front-look .demo-keys.dl-row > .dt-key { aspect-ratio: auto; min-height: 56px; flex-direction: column; gap: 4px; padding: var(--sp-1) var(--sp-2); font-size: var(--fs-sm); }
  .front-look .demo-keys.dl-row > .dt-key:not(.bad) { grid-column: span 2; box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .dt-keys.demo-keys > .dt-key.bad { order: 0; grid-row: auto; grid-column: span 1; box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
  /* the stations' key: a row under its line (the list's rows draw their own lines on a phone: the line under each) */
  .front-look .set-keys.dl-row > * { box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .set-keys.dl-row > .dt-key { grid-column: 1 / -1; flex-direction: row; aspect-ratio: auto; min-height: 52px; font-size: var(--fs-md); }
  /* a restaurant over its places: its band from edge to edge */
  .front-look .tbl-data.list-rows tr.set-grp { min-height: 0; padding: 0; background: var(--surface-2); }
  .front-look .tbl-data.list-rows tr.set-grp > th { display: block; flex: 0 0 100%; padding: var(--sp-2) var(--sx, 16px); box-shadow: inset 0 -1px 0 0 var(--zl); }
  /* «Профиль»: who a row, the keys a row under it — «Сменить устройство» two columns, «Выйти» one; a setting its name a
     column, the control two */
  .front-look .opf-who.dl-row > .profile-who { grid-column: 1 / -1; flex-direction: row; align-items: center; justify-content: flex-start; min-height: 72px; padding: var(--sp-2) var(--sx, 16px); }
  .front-look .opf-who.dl-row > .dt-key { grid-column: span 2; flex-direction: row; aspect-ratio: auto; min-height: 52px; font-size: var(--fs-md); }
  .front-look .opf-who.dl-row > .dt-key + .dt-key { grid-column: span 1; box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
  .front-look .opf-who.one.dl-row > .dt-key { grid-column: 1 / -1; }
  .front-look .opf-row.dl-row > .opf-l { grid-column: span 1; flex-direction: column; align-items: flex-start; justify-content: center; padding: var(--sp-2) var(--sp-2) var(--sp-2) var(--sx, 16px); }
  .front-look .opf-row.dl-row > .opf-l > .dl-cell-h { display: none; }
  /* (13 November, 12:31, the owner of «Профиль» on his iPhone: «Там не хватает линий») the line between a setting's name
