  .front-look .opf-row.dl-row > .opf-seg { grid-column: span 2; flex-direction: column; align-items: stretch; justify-content: center; padding: var(--sp-2) var(--sx, 16px) var(--sp-2) var(--sp-2); box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
  .front-look .opf-row.dl-row > .dt-key { grid-column: span 2; flex-direction: row; aspect-ratio: auto; min-height: 52px; font-size: var(--fs-md); box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
