/* (the prototype) the name on the devices: the field its whole cell */
:root .front-look .loc-table > .loc-card > .loc-dl > .loc-own-cell { padding: 0; }
.front-look .loc-own-cell > .dl-form { display: flex; flex: 1 1 auto; min-width: 0; height: 100%; }
.front-look .loc-own-cell .dt-field { display: flex; flex: 1 1 auto; flex-direction: column; justify-content: center; gap: 2px; min-width: 0; min-height: 72px; padding: var(--sp-2) var(--px); cursor: text; }
.front-look .loc-own-cell .dt-field-l { display: none; }
.front-look .loc-own-cell .dt-field > input { min-width: 0; height: 24px; padding: 0; border: 0; border-radius: 0; background: none; color: var(--ink); font: inherit; font-size: var(--fs-sm); outline: 0; }
:root .front-look .loc-own-cell .dt-field { background: transparent; box-shadow: none; }
:root .front-look .loc-own-cell .dt-field:focus-within { box-shadow: inset 0 -2px 0 0 var(--accent); }
/* the company's row: four cells and the key to the rest */
.front-look .dt-keys.loc-co-row { grid-template-columns: repeat(5, minmax(0, 1fr)); }
.loc-co-cell { display: flex; flex-direction: column; justify-content: center; gap: 2px; min-width: 0; min-height: 64px; padding: var(--sp-2) var(--px); border: 0; border-radius: 0; background: var(--surface); color: var(--ink); font: inherit; text-align: left; cursor: pointer; }
.loc-co-cell:hover { background: var(--surface-2); }
.loc-co-cell:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.loc-co-cell > .dl-cell-l { color: var(--ink-2); font-size: var(--fs-sm); line-height: 18px; }
.loc-co-cell > b { overflow: hidden; font-size: var(--fs-md); font-weight: var(--fw-semibold); line-height: 20px; white-space: nowrap; text-overflow: ellipsis; }
/* the store's products, what is below the minimum under them */
.front-look .loc-table .loc-dl dd.loc-two { flex-direction: column; flex-wrap: nowrap; align-items: flex-start; gap: 0; }
@media (max-width: 700px) {
  :root .front-look .loc-th { display: none; }
  .front-look .loc-table .loc-dl dd.loc-two { align-items: flex-end; }
  .front-look .loc-table > .loc-card { grid-template-columns: minmax(0, 1fr); }
  .front-look .loc-table > .loc-card > .loc-who { min-height: 56px; padding: var(--sp-2) 52px var(--sp-2) var(--sx, 16px); background: var(--surface-2); }
  .front-look .loc-table > .loc-card > .loc-dl > div { flex-direction: row; align-items: center; justify-content: space-between; gap: var(--sp-3); min-height: 52px; padding: var(--sp-2) var(--sx, 16px); box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .loc-table .loc-dl dt { display: block; flex: none; color: var(--ink); font-size: var(--fs-md); line-height: 22px; }
  .front-look .loc-table .loc-dl dd { justify-content: flex-end; min-width: 0; color: var(--ink-2); text-align: right; }
  .front-look .loc-own-cell .dt-field { flex-direction: row; align-items: center; justify-content: space-between; gap: var(--sp-3); min-height: 52px; padding: 0 var(--sx, 16px); }
  .front-look .loc-own-cell .dt-field-l { display: block; flex: none; color: var(--ink); font-size: var(--fs-md); line-height: 22px; }
  .front-look .loc-own-cell .dt-field > input { flex: 1 1 auto; color: var(--ink-2); font-size: var(--fs-md); text-align: right; }
  .front-look .dt-keys.loc-co-row { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  :root .front-look .dt-keys.loc-co-row > * { aspect-ratio: auto; min-height: 64px; }
  :root .front-look .dt-keys.loc-co-row > .loc-co-cell { padding: var(--sp-2) var(--sx, 16px); }
  :root .front-look .dt-keys.loc-co-row > .loc-co-cell:nth-child(odd) { box-shadow: inset 0 -1px 0 0 var(--zl); }
  :root .front-look .dt-keys.loc-co-row > .dt-key { grid-column: 1 / -1; flex-direction: row; min-height: 52px; font-size: var(--fs-md); box-shadow: inset 0 -1px 0 0 var(--zl); }
}

/* (12 November, «Изменить зал» on «Места реализации») one restaurant: the words three columns, the key two; several: the
   words across, a key each */
.front-look .places-keys:not(.many) > .dt-key { grid-column: span 2; }
@media (max-width: 700px) { .front-look .places-keys:not(.many) > .dt-key { grid-column: 1 / -1; } }
/* the iPad's plan editor over the back office: the whole window, above the sidebar and the sheets */
.he-office { position: fixed; inset: 0; z-index: 90; display: flex; background: var(--bg); }
.he-office > .app.ipad { flex: 1 1 auto; min-width: 0; height: 100%; }
:root.he-open, :root.he-open body { overflow: hidden; }
/* a phone: the editor's header two rows — «‹» and «Изменить зал», then the halls, «Новый зал» and «Сохранить» */
@media (max-width: 700px) {
  .he-office .ipad .ph-head { grid-template-columns: auto minmax(0, 1fr); row-gap: var(--sp-2); padding-bottom: var(--sp-3); }
  .he-office .ipad .ph-left { padding-left: var(--sp-4); }
  .he-office .ipad .ph-right { grid-column: 1 / -1; flex-wrap: wrap; justify-content: flex-start; gap: var(--sp-2); padding: 0 var(--sp-4); }
  .he-office .ipad .ph-right :is(.he-halls, .he-actions) { flex-wrap: wrap; }
}
/* several restaurants: «Изменить зал» an accent word at the right of each one's name; a restaurant's name under the one
   before it with a line between them (the last row of a restaurant draws none) */
.front-look .set-cols tr.set-grp > th .set-grp-in { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-3); min-width: 0; }
.front-look .set-grp-key { position: relative; display: inline-flex; flex: none; align-items: center; gap: 6px; min-height: 32px; padding: 0; border: 0; background: none; color: var(--accent); font: inherit; font-size: var(--fs-sm); font-weight: var(--fw-semibold); cursor: pointer; }
.front-look .set-grp-key:hover { text-decoration: underline; }
@media (min-width: 701px) { .front-look .set-cols tbody + tbody > tr.set-grp > th { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); } }
/* the accent word's touch: the whole height of the name's row (44 px on a phone) without making the row taller */
.front-look .set-grp-key::after { content: ''; position: absolute; inset: -6px calc(-1 * var(--px)) -6px -8px; }
/* a phone: the name's row 44 px with the key in its middle (the head cells' 44 px held it, the key's 32 px overflowed) */
@media (max-width: 700px) { .front-look .tbl-data.list-rows tr.set-grp > th { height: auto; padding-top: 6px; padding-bottom: 6px; } }
/* (0.107) who signed in last and since when it is connected: a line of its own, wrapped on a phone rather than cut */
.front-look .dev-table td.dev-who > .dev-more { white-space: normal; }

/* ---------- the lines between rows, on every page (11 November, 14:18) ----------
   The owner, going through the pages in the dark theme: «Здесь у нас отсутствует линия горизонтальная опять. Я, честно
   говоря, каждый раз за тобой ходить и говорить про горизонтальные линии выглядит как бред, с учётом того, какой ты
   умный». A page is rows one on another and a line between every two of them; test/rules-audit.mjs (no-line) reads them
   off the screen in both themes — a shade that only changes (a table's head on the page's ground) is not a line. */

/* a block's head and what comes under it: the head draws only the line over itself, so the note and the table's head
   under it draw the one between them */
.front-look .pg-block > .pg-head + :is(.dp-note, .empty) { box-shadow: inset 0 1px 0 0 var(--zl); }
.front-look .pg-block > :is(.pg-head, .dp-note) + .table-wrap > .tbl-data > thead > tr:first-child > th,
.front-look .pg-block > :is(.pg-head, .dp-note) + .tbl-data > thead > tr:first-child > th,
.front-look :is(.pg-nums, .kpi-row) + .pg-block > .table-wrap:first-child > .tbl-data > thead > tr:first-child > th { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
/* (12 November, 01:58, the owner: «Частая проблема — вторые горизонтальные линии расходятся. Почти во всех окнах») the
   page's first row stands under its head as the sidebar's restaurant row does (48 high), and the line under it is that
   row's line: the first block's head draws it at its own foot (y 111), not what is under it at its top (y 112) — so the
   note, the empty block or the table's head under the first block's head draw no line over themselves */
.front-look .of-page > .of-head + .pg-block > .pg-head:first-child { box-shadow: inset 0 1px 0 0 var(--line-2), inset 0 -1px 0 0 var(--zl); }
.front-look .of-page > .of-head + .pg-block > .pg-head:first-child > .pg-hkey { box-shadow: inset 1px 0 0 0 var(--zl), inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
.front-look .of-page > .of-head + .pg-block > .pg-head:first-child + :is(.dp-note, .empty) { box-shadow: none; }
/* («Деньги»' rows draw the line over themselves: the first one under the first block's head none — the head's is it) */
.front-look .of-page > .of-head + .pg-block > .pg-head:first-child + .tg-row { box-shadow: none; }
.front-look .of-page > .of-head + .pg-block > .pg-head:first-child + .table-wrap > .tbl-data > thead > tr:first-child > th,
.front-look .of-page > .of-head + .pg-block > .pg-head:first-child + .tbl-data > thead > tr:first-child > th { box-shadow: inset 0 -1px 0 0 var(--zl); }
/* (12 November, 02:07, the owner: «Кое-где встречаются двойные линии») the staff's tiles under the search's row: the row's
   line under it is the one between them — the tiles draw none over themselves */
.front-look .dt-keys + .pg-block > .pp-tiles:first-child { box-shadow: none; }

/* («Сколько стоит бизнес»: the keys' row and the table close themselves with their own lines — the note under each draws
   none over itself, not a second line a pixel under theirs) */
.front-look .mb-block > :is(.dt-keys, .worth-table, .table-wrap) + .tg-row { box-shadow: none; }

/* («Подключения» → Telegram: the steps' numbers inside the block's padding, as the words over them — not at its edge) */
.front-look .mb-block > .tg-steps { margin: 0; padding: var(--sp-2) var(--px) var(--sp-3) calc(var(--px) + 1.3em); }

/* a page closes with a line under its last row (a list's last row has its own: one pixel, drawn twice, is one line) —
   «Деньги»' blocks close themselves; a page that ends with tiles — their short last row leaves the ground after it —
   keeps the tiles' own lines */
.front-look:not(.mn-app) .of-page:not(:has(> :last-child :is(.pp-tiles, .dir-grid, .rg-grid, .wg-board)))::after { content: ''; flex: none; height: 0; margin-top: -1px; border-top: 1px solid var(--zl); }
/* (14 November, 04:38, the owner on «Консоль RUVO»: «Двойная линия») a block of «Деньги»' kind (.mb-block) on another page
   closes with its line outside it — under the page's own closing line it was a second one: the page's line alone. And a
   row of figures closes with its own line: the block's head right under it draws none over itself */
.front-look:not(.mn-app) .of-page:not(:has(> :last-child :is(.pp-tiles, .dir-grid, .rg-grid, .wg-board))) > .mb-block:last-child { box-shadow: none; }
.front-look .of-page > .kpi-row:not([data-tail]) + .pg-block > .pg-head:first-child { box-shadow: none; }
.front-look .of-page > .kpi-row:not([data-tail]) + .pg-block > .pg-head:first-child > .pg-hkey:not(.acc) { box-shadow: inset 1px 0 0 0 var(--zl); }

/* (the owner on «Скидки и акции»: «Четвёрка к чему относится? Она ничем не выделена») how many a list has stands by its
   name, quiet — not at the head's far end */
.pg-head h2 > .pg-n { margin-left: var(--sp-2); color: var(--ink-3); font-weight: var(--fw-regular); font-variant-numeric: tabular-nums; }

/* (the owner: «вкл идёт вот на этом уровне горизонтальном. Вот здесь вкл идёт на другом уровне. То есть столбцы разных
   таблиц должны быть на одном уровне») the discounts' two lists on the five columns: the name one, what it gives two,
   when — or who confirms — one, «Вкл.» the last */
@media (min-width: 701px) {
  .front-look .disc-table { table-layout: fixed; width: 100%; }
  .front-look .disc-table > colgroup > .dc-1 { width: 20%; }
  .front-look .disc-table > colgroup > .dc-2 { width: 40%; }
  .front-look .disc-table > colgroup > .dc-3 { width: 20%; }
  .front-look .disc-table > colgroup > .dc-4 { width: 20%; }
  .front-look .disc-table td { overflow: hidden; text-overflow: ellipsis; }
  .front-look .disc-table .title-row { flex-wrap: wrap; row-gap: 0; }
}

/* a document's lines and «+ Добавить продукт» under them: the bar draws the line over it too */
.front-look :is(.table-wrap, .tbl-data) + .lines-bar { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
/* the recipes' list (Техкарты): a line under each dish and under each folder's name */
.front-look .tech-list .tl-row, .front-look .tech-list .tl-cat { box-shadow: inset 0 -1px 0 0 var(--zl); }
@media (max-width: 700px) {
  /* a phone's list has no head of its columns: its first row draws the line under the block's head */
  .front-look .pg-block > :is(.pg-head, .dp-note) + .table-wrap > .tbl-data.list-rows > tbody:first-of-type > tr:first-child { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
  /* (12 November, the visual audit) …but the page's first block draws its head's line itself (the line under the
     sidebar's restaurant row): its list's first row draws none over it — two lines had touched («Скидки и акции») */
  .front-look .of-head + .pg-block > .pg-head + .table-wrap > .tbl-data.list-rows > tbody:first-of-type > tr:first-child { box-shadow: inset 0 -1px 0 0 var(--zl); }
  /* (the same audit) the page's choice under its head on a phone (a row of its own, its line under it) and the figures'
     squares after it: their first row draws no line over itself («Кассовые смены») */
  .front-look .of-head:has(> .of-actions > .select) + .pg-nums > [data-r0] { box-shadow: inset 1px 0 0 0 var(--line-2), var(--rim, 0 0 #0000); }
  .front-look .of-head:has(> .of-actions > .select) + .pg-nums > [data-r0][data-rf] { box-shadow: var(--rim, 0 0 #0000); }
}

/* ---------- the popups, one order for all of them (11 November, 14:18) ----------
   The owner on «Приход по фото»: «кнопка, которая не отцентрована по левому краю. Здесь отступ до линии один, от линии
   отступ другой. Почему-то вот этот текст идёт наполовину только блока … Здесь линия, пустое место. Вот здесь вот эта
   кнопка откуда?»; on «Списание»: «Вот эти две линии зачем? Отступы все разные. Кнопка идёт с левого края … здесь легче
   использовать пилюлю … для сравнения тебе креста такой каши нету, всё чётко … надо исправить и пробежаться точно по всем
   попапам». A sheet (a window rounded at 16):
   - its head — the name, what it is of — as far from the line under it (12) as the words under that line are from it;
   - its rows from edge to edge (fields, switches, a table, a list) start right on the head's line and end right on the
     foot's: one line there, never two with a strip between;
   - its words from the head's left edge, the whole width;
   - its keys are pills (as the cross), from that same edge. */
.front-look .sheet-head { flex: none; min-height: 0; padding: var(--sp-3) var(--sp-3) var(--sp-3) var(--sx); }
.front-look .sheet-head .sheet-titles { gap: 2px; padding: 0; }
.front-look .sheet-head > .icon-btn { margin-block: -8px; }
.front-look .sheet-body { --sheet-top: var(--sp-3); padding-top: var(--sheet-top); padding-bottom: var(--sheet-top); }
/* (13 November, 01:38, the owner's phone, «Топ блюд»: «Узко в первом пункте по высоте») a body of no padding of its own
   (flush) pulls nothing up: its first row had gone 12 under the head — the first dish lower than the others —, its last
   12 past the sheet's end */
.front-look .sheet-body.flush { --sheet-top: 0px; }
/* rows from edge to edge at the top and at the bottom of a sheet */
.front-look .sheet-body > :first-child:is(.form-row, .mn-form, .day-row, .cur-row, .fc-set, .loc-name, .check-row, .lines-bar, .tbl-data, .table-wrap, .chip-row.grp-chips, .form-acts, .tech-link, .sef-sheet, .scan-pick, .sp-group),
.front-look .sheet-body > .field:first-child:has(> :is(input, textarea, .select, .site-slug, .site-color, .chip-row, .toggle-row, .seg, .stepper, .field-static, .dish-photo)) { margin-top: calc(-1 * var(--sheet-top)); }
.front-look .sheet-body > :last-child:is(.form-row, .mn-form, .day-row, .cur-row, .fc-set, .loc-name, .check-row, .lines-bar, .tbl-data, .table-wrap, .form-acts, .tech-link, .sp-group),
.front-look .sheet-body > .field:last-child:has(> :is(input, textarea, .select, .site-slug, .site-color, .chip-row, .toggle-row, .seg, .stepper, .field-static, .dish-photo)) { margin-bottom: calc(-1 * var(--sheet-top)); }
/* (12 November, 02:44, the owner on «Новый гость»: «Две линии») the switches' rows straight under the fields — the fields'
   last line their top, no strip — and, at the sheet's end, ending on its foot's line: one line there, not two */
.front-look .sheet-body > .field + .check-list { margin-top: calc(-1 * var(--gap, var(--sp-4))); }
.front-look .sheet-body > .check-list:last-child { margin-bottom: calc(-1 * var(--sheet-top)); }
.front-look .sheet-body > .check-list:last-child > .check-row:last-child { box-shadow: none; }
/* (the visual audit of the lines, 12 November: «Блюдо», «Папки») the same inside a part of the form — the switches right
   under the prices' fields —, and a sheet that ends on a part ending with its switches, or on the folders' list: its last
   row on the foot's line, not a line, a strip, the foot's line */
.front-look .sheet-body > .form-section > :is(.form-row, .field) + .check-list { margin-top: calc(-1 * var(--gap, var(--sp-2))); }
.front-look .sheet-body > :is(.form-section:has(> :is(.check-list, .form-row, .day-row, .cur-row, .field):last-child), .folders):last-child { margin-bottom: calc(-1 * var(--sheet-top)); }
/* (a discount's «Весь день», then the hours' fields; a payment method's «Где выбирают», then «Сверка с кассой»: the
   fields' line on the switches', no strip) */
.front-look .sheet-body > :is(.check-list, .form-section:has(> .check-list:last-child)) + :is(.form-row, .day-row, .cur-row, .fc-set, .loc-name, .field) { margin-top: calc(-1 * var(--gap, var(--sp-4))); }
.front-look .sheet-body > .form-section:last-child > .check-list:last-child > .check-row:last-child,
.front-look .sheet-body > .folders:last-child > .folder:last-child { box-shadow: none; }
.front-look .sheet-body > .form-section:last-child > .check-list:last-child > .check-row:first-child:last-child { box-shadow: inset 0 1px 0 0 var(--zl); }
/* (12 November, 11:06, the owner's screenshot of «Где продаётся» on a phone: under «Сайт» a line, a strip, the foot's
   line) the dish's switches the sheet's whole body: its last row stands on the foot's line */
/* (13 November, 01:14, the owner's phone, «Что сделать» opened from «Сводка»: «Подстава» — its rows in from the sheet's
   edges, a line of their own a strip under the head's, the norm's row and the tips' apart, their words further in than
   the head's) a list of rows in a sheet (ui/tips.jsx): edge to edge, the head's line over its first row, the lists one
   after another as one list, the words from the head's edge, the sheet's edge under the last */
.front-look .sheet-body > :is(.mb-list, .todo-more-row) { margin-inline: calc(-1 * var(--edge, var(--sx))); }
.front-look .sheet-body > .mb-list:first-child { margin-top: calc(-1 * var(--sheet-top)); }
.front-look .sheet-body > .mb-list:first-child > .mb-item:first-child { --tl: 0 0 #0000; }
.front-look .sheet-body > .mb-list + :is(.mb-list, .todo-more-row) { margin-top: calc(-1 * var(--gap, var(--sp-4))); }
.front-look .sheet-body > :is(.mb-list, .todo-more-row):last-child { margin-bottom: calc(-1 * var(--sheet-top)); }
.front-look .sheet-body > .mb-list > .mb-item > .mb-w { padding-inline: var(--edge, var(--sx)); }
.front-look .sheet-body > .dp-sells.dp-rows:last-child { margin-bottom: calc(-1 * var(--sheet-top)); }
.front-look .sheet-body > .dp-sells.dp-rows:last-child > .dp-sell:last-child { box-shadow: none; }
/* (the deeper check of the lines, 12 November: the dish's sheet — its last switches, then «Убрать из меню» with its own
   line: a line of 2 px) switches right over the acts: the act's line is the one between them */
.front-look .sheet-body > .form-section:has(+ .form-acts) > .check-list:last-child > .check-row:last-child,
.front-look .sheet-body > .check-list:has(+ .form-acts) > .check-row:last-child { box-shadow: none; }
/* (12 November, 03:36, the owner on «Приход по фото»: «Тоже тесно») a sheet that opens with words: room over them as
   under the head's (the head's line not on top of the first line of words) */
.front-look .sheet-body > .scan-pick:first-child { padding-top: var(--sp-2); }
/* (a sheet that only opens as its first row — the invoice's facts, the photo's step — takes its own first row up) */
.front-look .sheet-body > :is(.sef-sheet, .scan-pick):first-child { margin-top: 0; }
/* a row of cells, then a part that opens with its switches' rows (the kiosk: «Период | Ресторан», then «Спрашивать
   телефон гостя»): one line between them, not two with a strip of the body's gap */
/* (a part of the form keeps its own --gap, 8: the sheet's 16 is said outright) */
.front-look .sheet-body > :is(.form-row, .day-row, .cur-row, .fc-set, .loc-name) + .form-section:has(> .check-list:first-child) { margin-top: calc(-1 * var(--sp-4)); }
/* words: the whole width */
.front-look .sheet-body :is(.scan-lead, .sheet-lead, .form-hint) { max-width: none; }

/* «+ Добавить продукт» under a document's lines in a sheet: a pill from the words' edge, in a row of its own (on a page
   it stays a key of the row) */
.front-look .sheet-body > .lines-bar { align-items: center; }
.front-look .sheet-body > .lines-bar > .lines-add { min-height: 40px; margin: var(--sp-2) 0 var(--sp-2) var(--edge, var(--sx)); padding: 0 var(--sp-4) 0 var(--sp-3); border-radius: var(--r-pill); background: var(--surface-3); color: var(--ink); font-weight: var(--fw-semibold); }
.front-look .sheet-body > .lines-bar > .lines-add > svg { color: var(--ink-2); }
.front-look .sheet-body > .lines-bar > .lines-add:hover { background: color-mix(in oklab, var(--surface-3) 80%, var(--ink)); }

/* «Приход по фото»: the camera and the file — pills from the words' edge (the camera the accent's) */
.front-look .scan-pick > .scan-take { display: flex; flex-wrap: wrap; gap: var(--sp-3); margin: 0; box-shadow: none; }
:root .front-look .scan-pick > .scan-take > .btn { flex: 0 1 auto; min-height: 48px; margin: 0; padding: 0 var(--sp-5); border: 0; border-radius: var(--r-pill); justify-content: center; text-align: center; }
.front-look .scan-pick > .scan-take > .btn.btn-primary { background: var(--accent); color: var(--accent-ink); }
.front-look .scan-pick > .scan-take > .btn.btn-secondary { background: var(--surface-3); color: var(--ink); box-shadow: none; }
.front-look .scan-pick > .scan-take > .btn.btn-secondary:hover:not(:disabled) { background: color-mix(in oklab, var(--surface-3) 80%, var(--ink)); }
@media (max-width: 700px) {
  .front-look .scan-pick > .scan-take { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--sp-2); }
  :root .front-look .scan-pick > .scan-take > .btn { width: 100%; }
}
/* «Недавние фото»: rows from edge to edge (the list bleeds to the sheet's edges in 99-sef.css, its rows keep the words'
   edge), a line between them; the list is the step's last thing on the screen (only the two hidden file inputs after
   it), so its last row ends the sheet — no line under it, no air */
.front-look .scan-recent { gap: 0; }
.front-look .scan-recent > .caption { padding-bottom: var(--sp-2); }
.front-look .scan-recent > p { margin: 0; }
.front-look .scan-pick .scan-recent-row { border-bottom-color: var(--zl); }
.front-look .sheet-body > .scan-pick:last-child { margin-bottom: calc(-1 * var(--sheet-top)); }
.front-look .sheet-body > .scan-pick:last-child .scan-recent-list > li:last-child > .scan-recent-row { border-bottom: 0; }
.front-look .sheet-body > .scan-pick:last-child .scan-recent > p:last-child { padding-bottom: var(--sheet-top); }

/* the invoice from SEF: its facts edge to edge (the one before the note across the row too — no empty grey cell); the
   note two lines until opened; the totals rows of the lines above them, not a corner of their own */
.front-look .sheet-body > .sef-sheet > .sef-facts > div:nth-child(odd):has(+ div.wide) { grid-column: 1 / -1; }
.front-look .sef-facts > div.wide > dd.sef-note-t { display: -webkit-box; overflow: hidden; -webkit-line-clamp: 2; -webkit-box-orient: vertical; cursor: pointer; }
.front-look .sef-facts > div.wide > dd.sef-note-t.open { display: block; }
.front-look .sheet-body > .sef-sheet > .sef-totals { justify-content: stretch; gap: 0; margin: 0 calc(-1 * var(--edge)); padding: 0; }
.front-look .sheet-body > .sef-sheet > .sef-totals > div { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-3); min-height: 44px; padding: 0 var(--edge); box-shadow: inset 0 -1px 0 0 var(--zl); }
.front-look .sheet-body > .sef-sheet > .sef-totals dt { color: var(--ink-2); text-align: left; }
.front-look .sheet-body > .sef-sheet > .sef-totals .sum { min-height: 52px; padding-top: 0; border-top: 0; }
.front-look .sheet-body > .sef-sheet > .sef-totals .sum :is(dt, dd) { color: var(--ink); font-size: var(--fs-md); }
.front-look .sheet-body > .sef-sheet > .sef-totals + p { box-shadow: none; }

/* (the visual audit of the lines, 12 November: «Инвентаризация») a table under words: its head's own shade had been its only
   edge — a line over it */
.front-look .sheet-body > :is(p, .fld-note, .form-hint) + .tbl-data > thead > tr > th,
.front-look .sheet-body > :is(p, .fld-note, .form-hint) + .table-wrap > .tbl-data > thead > tr > th { box-shadow: inset 0 1px 0 0 var(--zl), inset 0 -1px 0 0 var(--zl); }
@media (max-width: 700px) {
  /* («Приход», «Списание» on a phone) the lines' last row draws its line: «+ Добавить продукт» none over itself */
  .front-look .sheet-body > :is(.table-wrap, .tbl-data) + .lines-bar { box-shadow: inset 0 -1px 0 0 var(--zl); }
  .front-look .sheet-body > :is(.table-wrap, .tbl-data) + .lines-bar:last-child { box-shadow: none; }
}
/* (the visual audit of the lines, 12 November) the kiosk's «Период | Ресторан», then its first switch; a field, then the
   terminal's «Проверить связь»: one line between them, no strip */
.front-look .sheet-body > .form-row + .form-section.ko-sec { margin-top: calc(-1 * var(--sp-4)); }
.front-look .sheet-body > :is(.field, .form-row) + .form-acts { margin-top: calc(-1 * var(--gap, var(--sp-4))); }
/* a sheet that ends on its keys' rows (the terminal's check's words not there yet) or on the QR's sample: on the foot's line */
.front-look .sheet-body > :is(.form-acts, .ips-preview):is(:last-child, :has(+ .term-check:empty:last-child)) { margin-bottom: calc(-1 * var(--sheet-top)); }
.front-look .sheet-body > .form-acts:is(:last-child, :has(+ .term-check:empty:last-child)) > .form-act:last-child { box-shadow: none; }
:root:root .front-look .sheet-body > .form-acts:not(:first-child):is(:last-child, :has(+ .term-check:empty:last-child)) > .form-act:first-child:last-child { box-shadow: inset 0 1px 0 0 var(--zl); }
/* (12 November, the deep visual audit of «Деньги»: «Корректировка», «Новый PIN» framed boxes of the old look beside a
   pill — a strip under their frames) a card's second key in its foot: a word with its icon, as «Отмена» */
.front-look .sheet-foot > .btn-secondary { border-color: transparent; background: none; box-shadow: none; }
.front-look .sheet-foot > .btn-secondary:hover:not(:disabled) { background: var(--surface-2); }
/* (the deeper check, 12 November: a modifier group's sheet — «+ Вариант» closing its list with its line, a strip, then
   «Удалить группу» with its own line) acts right under a part that ends with an act: one line between them */
.front-look .sheet-body > .form-section:has(> .form-act:last-child) + .form-acts { margin-top: calc(-1 * var(--gap, var(--sp-4))); box-shadow: none; }
:root:root:root:root .front-look .sheet-body > .form-section:has(> .form-act:last-child) + .form-acts > .form-act:first-child { box-shadow: none; }

/* ---------- a sheet's keys on a phone: the waiter's (13 November) ----------
   (12:43, the owner of the back office on his iPhone: «Вот такие вещи сразу исправляй. По примеру официантского») a
   sheet of the back office on a phone ends as the waiter's sheets do (50-phone.css, «the foot's pills»): its keys pills
   56 high, 16 from the sheet's edges, 8 apart, above the home bar, hanging over the body — what scrolls under them
   fades into the sheet's white, and the body keeps room under its last row so it scrolls clear of them. Two keys, the
   second the main one: the first on the waiter's line, a third of the sheet, the main one the rest. «Отмена»,
   «Назад», «Закрыть» ink — black by day, white at night —, the main one its own colour, «Удалить» red on its light
   shade. Three keys and more: the main one a row of its own under the others. The foot's words (a document's lines and
   sum, «Удалить «…»?») a row of their own over the keys. A sheet with no keys ends above the home bar. */
.front-look.of-phone { --fade-h: 28px; --fade-0: rgb(255 255 255 / 0); }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) .front-look.of-phone { --fade-0: rgb(22 25 32 / 0); } }
:root[data-theme="dark"] .front-look.of-phone { --fade-0: rgb(22 25 32 / 0); }
.front-look.of-phone .sheet:has(> .sheet-foot) {
  position: relative; --foot-keys: 56px; --foot-words: 0px;
  --foot-room: calc(var(--foot-words) + var(--foot-keys) + max(var(--sp-3), env(safe-area-inset-bottom, 0px)) + var(--fade-h));
}
.front-look.of-phone .sheet:has(> .sheet-foot > .grow:not(:empty)) { --foot-words: 40px; }
.front-look.of-phone .sheet:has(> .sheet-foot > .btn ~ .btn ~ .btn):has(> .sheet-foot > :is(.btn-primary, .btn-ok, .btn-danger)) { --foot-keys: calc(2 * 56px + var(--sp-2)); }
.front-look.of-phone .sheet:has(> .sheet-foot) > .sheet-body::after { content: ''; display: block; flex: none; height: var(--foot-room); }
.front-look.of-phone .sheet > .sheet-foot {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 2;
  display: flex; flex-wrap: wrap; align-items: stretch; justify-content: stretch; gap: var(--sp-2);
  padding: 0 var(--sp-4) max(var(--sp-3), env(safe-area-inset-bottom, 0px)); border-top: 0; background: none; pointer-events: none;
}
.front-look.of-phone .sheet > .sheet-foot::before {
  content: ''; position: absolute; z-index: -1; left: 0; right: 0; top: calc(var(--fade-h) * -1); bottom: 0; pointer-events: none;
  background: linear-gradient(to bottom, var(--fade-0), var(--surface) calc(var(--fade-h) + 6px));
}
.front-look.of-phone .sheet > .sheet-foot > .btn {
  position: relative; flex: 1 1 0; min-width: 0; height: 56px; min-height: 0; margin: 0; padding: 0 var(--sp-4);
  justify-content: center; border: 0; border-radius: var(--r-pill); box-shadow: 0 4px 14px rgb(0 0 0 / 0.16), 0 1px 3px rgb(0 0 0 / 0.1);
  font-size: var(--fs-md); font-weight: var(--fw-semibold); pointer-events: auto; transition: transform 0.08s;
}
.front-look.of-phone .sheet > .sheet-foot > .btn > svg { color: currentColor; }
.front-look.of-phone .sheet > .sheet-foot > .btn .btn-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.front-look.of-phone .sheet > .sheet-foot:not(:has(> .btn ~ .btn ~ .btn)):has(> .btn ~ :is(.btn-primary, .btn-ok, .btn-danger)) > .btn:not(.btn-primary, .btn-ok, .btn-danger) {
  flex: 0 0 calc((100% + 2 * var(--sp-4)) / 3 - var(--sp-4) - var(--sp-1));
}
.front-look.of-phone .sheet > .sheet-foot:has(> .btn ~ .btn ~ .btn) > :is(.btn-primary, .btn-ok, .btn-danger) { flex: 1 0 100%; order: 2; }
.front-look.of-phone .sheet > .sheet-foot > :is(.btn-ghost, .btn-secondary),
.front-look.of-phone .sheet > .sheet-foot > :is(.btn-ghost, .btn-secondary):hover:not(:disabled) { border-color: transparent; background: var(--ink); color: var(--surface); }
.front-look.of-phone .sheet > .sheet-foot > .btn-danger-ghost,
.front-look.of-phone .sheet > .sheet-foot > .btn-danger-ghost:hover:not(:disabled) { background: var(--bad-soft); color: var(--bad); }
/* (a touch screen keeps :hover after a tap: the keys keep their colour and answer the finger with :active) */
.front-look.of-phone .sheet > .sheet-foot > .btn-primary:hover:not(:disabled) { background: var(--accent); }
.front-look.of-phone .sheet > .sheet-foot > .btn-primary:active:not(:disabled) { background: var(--accent-2); }
.front-look.of-phone .sheet > .sheet-foot > .btn:active:not(:disabled) { transform: scale(0.97); }
.front-look.of-phone .sheet > .sheet-foot > .btn:disabled { opacity: 1; background: var(--pill-press); color: var(--ink-3); box-shadow: none; }
.front-look.of-phone .sheet > .sheet-foot > .grow:empty { display: none; }
.front-look.of-phone .sheet > .sheet-foot > .grow:not(:empty) {
  flex: 1 0 100%; order: -1; min-width: 0; min-height: 0; margin: 0; padding: var(--sp-2) var(--sp-1) 0;
  font-size: var(--fs-sm); line-height: 20px; text-align: left;
}
.front-look.of-phone .sheet:not(:has(> .sheet-foot)) > .sheet-body:last-child { padding-bottom: max(var(--sheet-top, var(--sp-3)), env(safe-area-inset-bottom, 0px)); }
/* (the same day) a toast on the owner's phone as the waiter's (50-phone.css, .toasts-phone): a pill, its words 16
   semibold, good news the ink — black by day, white at night —, low on the screen above the home bar; while a sheet with
   keys is open, 12 above its pills */
.front-look.of-phone > .toasts { bottom: max(var(--sp-5), env(safe-area-inset-bottom, 0px)); }
.front-look.of-phone:has(.sheet > .sheet-foot) > .toasts { bottom: calc(56px + max(var(--sp-3), env(safe-area-inset-bottom, 0px)) + var(--sp-3)); }
.front-look.of-phone > .toasts .toast { border-radius: var(--r-pill); font-size: var(--fs-md); }
.front-look.of-phone > .toasts .toast-ok { background: var(--ink); color: var(--surface); }

/* ---------- the back office's colours: «A + B» (12 November, 03:10, the owner: «цвета A + B») ----------
   The owner, 02:02: «Я бы стандартизировал цвета, чтобы была понятна приоритетность блоков и информации (как на скриншоте
   — все серое)». The loudest thing on every screen had been the menu's chosen item, a filled blue band — the least of what
   one reads there. Now:
   A — the order of what one reads: a page's main figures on the raised surface and larger (their names stay a head's
       letters, the owner's rule of 10 November); the chosen item of the menu and of a page's tabs a blue mark (the menu's at its edge, a tab's under
       it) on the raised surface — blue fills only the keys that do something.
   B — colour only for meaning: red a problem to deal with now, amber something to look at, green all is fine (quietly);
       a block or a figure that needs one has its colour along its top and its ground tinted; the staff's departments have
       their own colour — the floor and the bar blue, the kitchen orange, the back office violet. */

/* A — the menu's chosen item: the raised surface, a blue mark at its edge, its icon blue */
:root .front-look :is(.of-nav-btn.on, .of-sub-btn.on, .of-group.in:not(.open) > .of-group-btn),
:root .front-look :is(.of-nav-btn.on, .of-sub-btn.on, .of-group.in:not(.open) > .of-group-btn):hover {
  background: var(--surface-2); color: var(--ink); box-shadow: inset 3px 0 0 0 var(--accent);
}
:root .front-look :is(.of-nav-btn.on, .of-sub-btn.on, .of-group.in:not(.open) > .of-group-btn) svg { color: var(--accent); }
:root .front-look .of-sub-btn.on { font-weight: var(--fw-semibold); }

/* A — a page's tabs and strips of choices: the chosen one raised, a blue line under it (as a chosen figure's) */
:root .front-look :is(.of-page > .seg, .sh-bar > .seg, .bk-daybar .seg, .card-head .seg, .card > .seg, .seg.seg-chips, .chip-row.grp-chips) > :is(.seg-btn, .chip).on {
  background: var(--surface-2); color: var(--ink); font-weight: var(--fw-semibold); box-shadow: inset 0 -3px 0 0 var(--accent);
}
:root .front-look :is(.of-page > .seg, .sh-bar > .seg, .bk-daybar .seg, .card-head .seg, .card > .seg, .seg.seg-chips, .chip-row.grp-chips) > :is(.seg-btn, .chip).on:not(:first-child) {
  box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -3px 0 0 var(--accent);
}
:root .front-look :is(.of-page > .seg, .sh-bar > .seg, .bk-daybar .seg, .card-head .seg, .card > .seg, .seg.seg-chips, .chip-row.grp-chips) > :is(.seg-btn, .chip).on:last-child:not(:first-child) {
  box-shadow: inset 1px 0 0 0 var(--zl), inset 0 -3px 0 0 var(--accent), 1px 0 0 0 var(--zl);
}

/* A — the main figures: a page's squares on the raised surface, the figure larger; «Сводка»'s revenue and its chart */
:root .front-look .pg-nums > .pg-num.ptable { background-color: var(--surface-2); }
:root .front-look .pg-nums > .pg-num.ptable.pg-key:hover { background-color: var(--surface-3); }
:root .front-look .pg-nums > .pg-num.ptable.pg-key.on { background-color: var(--surface-3); }
:root .front-look .wg-board > :is(.wg-num, .wg-rev), :root .front-look .wg-board > :is(.wg-num, .wg-rev) > * { background-color: var(--surface-2); }
@media (min-width: 701px) {
  :root .front-look .pg-num-v { font-size: 32px; line-height: 38px; }
  :root .front-look .wg-num .tile-big .tile-v { font-size: 40px; line-height: 48px; }
}

/* B — a block of «Сводка» that needs a look: amber (the kitchen slow, a product short), red (a guest's low mark not dealt
   with) — its colour along its top, its ground tinted */
:root .front-look .wg-board > .wg.wg-1:has(.bad-txt) { --tone: var(--bad); }
:root .front-look .wg-board > .wg.wg-1:not(:has(.bad-txt)):has(.warn-txt, .low-qty) { --tone: var(--warn); }
:root .front-look .wg-board > .wg.wg-1:is(:has(.bad-txt), :has(.warn-txt, .low-qty)) {
  background: linear-gradient(var(--tone), var(--tone)) top / 100% 3px no-repeat, color-mix(in oklab, var(--tone) 11%, var(--surface));
}
:root .front-look .wg-board > .wg.wg-1:is(:has(.bad-txt), :has(.warn-txt, .low-qty)) > * { background: transparent; }
/* B — a square that needs a look: amber (below the minimum, no PIN, short), red (a problem); all fine — its figure green */
:root .front-look .pg-nums > .pg-num:is(.pg-low, .pg-warn) { --tone: var(--warn); }
:root .front-look .pg-nums > .pg-num.pg-bad { --tone: var(--bad); }
:root .front-look .pg-nums > .pg-num:is(.pg-low, .pg-warn, .pg-bad) {
  background: linear-gradient(var(--tone), var(--tone)) top / 100% 3px no-repeat, color-mix(in oklab, var(--tone) 11%, var(--surface-2));
}
:root .front-look .pg-nums > .pg-num:is(.pg-low, .pg-warn, .pg-bad) .pg-num-v { color: var(--tone); }
/* B — the departments: a dot of their colour by the squares' names, the staff's avatars in it */
.pg-num-l > .dep-dot { display: inline-block; width: 10px; height: 10px; margin-right: 8px; border-radius: 3px; vertical-align: 1px; }
.dep-dot.dep-floor { background: var(--dep-floor); }
.dep-dot.dep-kitchen { background: var(--dep-kitchen); }
.dep-dot.dep-office { background: var(--dep-office); }
:root .front-look .avatar.dep-floor { background: color-mix(in oklab, var(--dep-floor) 22%, var(--surface)); color: var(--dep-floor); }
:root .front-look .avatar.dep-kitchen { background: color-mix(in oklab, var(--dep-kitchen) 22%, var(--surface)); color: var(--dep-kitchen); }
:root .front-look .avatar.dep-office { background: color-mix(in oklab, var(--dep-office) 22%, var(--surface)); color: var(--dep-office); }
